"vehicle_type_legacy":"bus_coach","anchor_poi_keys":["haedong_yonggungsa","cheongsapo_daritdol_observatory","cheongsapo_blue_line_park","gamcheon_culture_village","dakbatgol_mural_village"],"private_tour_fit":0.05,"customizable_route_fit":0.1,"flexibility_fit":0.3,"fixed_itinerary_fit":1,"buddhist_temple_fit":1,"scenic_temple_fit":1,"coastal_temple_fit":1,"seaside_temple_fit":1,"war_memorial_fit":1,"korean_war_history_fit":1,"mural_village_fit":1,"fish_market_fit":1,"market_fit":1,"street_food_fit":0.9,"skywalk_fit":1,"sky_capsule_fit":0.7,"coastal_railway_fit":1,"history_culture_fit":1,"k_drama_filming_fit":0.5,"religious_history_fit":0.85,"premium_dining_fit":0.3,"seasonal_fit":0.85,"china_mainland_market_fit":0,"korea_domestic_market_fit":0,"taiwan_market_fit":1,"singapore_market_fit":1,"hong_kong_market_fit":1,"china_diaspora_overseas_market_fit":0.95,"se_asia_market_fit":0.95,"us_market_fit":0.85,"europe_market_fit":0.85,"australia_market_fit":0.85,"japan_market_fit":0.85,"busan_signature_route_fit":1,"skywalk_coastal_railway_fit":1,"first_time_busan_fit":1,"no_inter_city_travel_fit":1,"differentiates_from_busan_gyeongju_routes":true,"deep_history_traveler_fit_minimum":0.7,"english_speaking_guide_provided":true,"chinese_speaking_guide_available_on_advance_notice":true,"japanese_speaking_guide_available_on_advance_notice":true},"matching_metadata":{"primary_themes":["busan","coastal","seaside_temple","sky_capsule","culture_village","mural_village","small_group"],"secondary_themes":["glass_skywalk","blueline_park","gamcheon","dakbatgol_monorail","photo_spots","free_admission_anchors","first_time_busan"],"best_for":["first_time_busan","couples","photo_lovers","adult_families","small_group_seekers"],"not_recommended_for":["minimal_walking_seekers","stroller_heavy_groups","nightlife_focused_travelers"],"anchor_pois":["Haedong Yonggungsa Temple","Cheongsapo Daritdol Observatory","Haeundae Blueline Park Sky Capsule","Gamcheon Culture Village","Dakbatgol Mural Village"],"anchor_poi_keys":["haedong_yonggungsa","cheongsapo_daritdol_observatory","cheongsapo_blue_line_park","gamcheon_culture_village","dakbatgol_mural_village"],"competing_products":["busan-top-attractions-day-tour","busan-small-group-sightseeing-tour-cruise-passengers","busan-private-car-charter-cruise-shore"],"reviews_attribution":"New product (2026-08) — no imported reviews; rating starts at 0.","unesco_fit_note":"No UNESCO property on this route. Cultural weight comes from the seaside temple (1376 founding), Korean-War refugee village heritage at Gamcheon, and hanji paper-mulberry heritage at Dakbatgol."},"itinerary_variants":[],"_publication":{"schema_version":"v4_canonical","created":"2026-08-04","last_modified":"2026-08-04","version_history":["v1_authored_2026_08_04"],"fix_passes":{"v1_authored_2026_08_04":"New product (owner instruction 2026-08-04). Donor: busan-top-attractions-day-tour — pickup/Yonggungsa/lunch-slot/Gamcheon stops, 3-station pickup_dropoff, Busan weather/glance/trust/support blocks reused per locale; Daritdol Observatory, Sky Capsule (ticket-optional), Dakbatgol Mural Village & wish-stairs monorail, and all product-level copy authored fresh in 6 locales (scripts/busan-smallgroup-content/). matching_profile derived from donor with identity/anchor patches — full KB calibration pending. Price set by owner (2026-08-04): USD 59 Sky Capsule ticket excluded / USD 79 ticket included. Daritdol and Dakbatgol ship without photos (no owned imagery yet)."}},"page_sections":[{"id":"hero","section_html_id":null,"component":"TourHeroSection","props":{"headlineLine1":"Meerestempel, Sky Capsule","headlineLine2":"& Kulturdörfer","hero":{"imageUrl":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","imagePosition":"center 40%","images":["/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp"],"tagline":"Busans Tempel am Meer zur stillen Stunde, ein Glas-Skywalk über dem Wasser, eine Pastellkapsel-Fahrt die Küste hinab und zwei Hangdörfer — eines berühmt, eines noch ganz lokal","pills":["Kleingruppe","Busan","Ideal für Erstbesucher"],"meta":{"duration":"≈ 10 Stunden (08:30 erste Abholung, ≈ 18:30 letzter zentraler Ausstieg)","region":"Busan","stops":"8 Stopps","rating":0,"ratingStars":0}}}},{"id":"subnav","section_html_id":null,"component":"TourTabsNav","props":{"subnavItems":[{"id":"overview","label":"Überblick"},{"id":"itinerary","label":"Tagesablauf"},{"id":"practical","label":"Praktisches"},{"id":"reviews","label":"Bewertungen"},{"id":"booking","label":"Buchung"}]}},{"id":"overview","section_html_id":"overview","component":"TourAtAGlance","props":{"glanceItems":[{"icon":"camera","label":"Fotopotenzial","value":"Hoch","level":5},{"icon":"mountain","label":"Landschaft","value":"Gut","level":4},{"icon":"footprints","label":"Gehaufwand","value":"Anspruchsvoll","level":4},{"icon":"cloud-rain","label":"Regentauglichkeit","value":"Mittel","level":3},{"icon":"users","label":"Familientauglichkeit","value":"Gut","level":4},{"icon":"gauge","label":"Tempo","value":"Ausgewogen","level":4}]}},{"id":"atmosphere","section_html_id":null,"component":"TourAtmosphereGallery","props":{"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 1","alt":"Haedong Yonggungsa Temple — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-haesu-gwaneum.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 2","alt":"Haedong Yonggungsa Temple — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-dragon-hall.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 3","alt":"Haedong Yonggungsa Temple — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-main-courtyard.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 4","alt":"Haedong Yonggungsa Temple — gallery image 4"},{"id":5,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-zodiac-statues.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 5","alt":"Haedong Yonggungsa Temple — gallery image 5"},{"id":6,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 6","alt":"Haedong Yonggungsa Temple — gallery image 6"},{"id":7,"type":"photo","src":"/images/tours/cheongsapo-blue-line/cheongsapo-sky-capsule-interior.webp","location":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo)","caption":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — photo 1","alt":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — gallery image 1"},{"id":8,"type":"photo","src":"/images/tours/cheongsapo-blue-line/blueline-tram-cherry-sea.webp","location":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo)","caption":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — photo 2","alt":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — gallery image 2"},{"id":9,"type":"photo","src":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-01-01-18.webp","location":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo)","caption":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — photo 3","alt":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — gallery image 3"},{"id":10,"type":"photo","src":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-12-53-19.webp","location":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo)","caption":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — photo 4","alt":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — gallery image 4"},{"id":11,"type":"photo","src":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 1","alt":"Gamcheon Culture Village — gallery image 1"},{"id":12,"type":"photo","src":"/images/tours/gamcheon-culture-village/chatgpt-image-2026-5-11-01-00-53.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 2","alt":"Gamcheon Culture Village — gallery image 2"},{"id":13,"type":"photo","src":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 3","alt":"Gamcheon Culture Village — gallery image 3"},{"id":14,"type":"photo","src":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-day-sign.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 8","alt":"Gamcheon Culture Village — gallery image 8"}]}},{"id":"itinerary","section_html_id":"itinerary","component":"TourTimelineSection","props":{"itineraryStops":[{"name":"Abholung (3 zentrale Stationen in Busan)","time":"≈ 08:30–09:30","number":1,"category":"Transfer / Abholung","duration":"30 Min.","timeUsed":["Abholung Bahnhof Busan (~09:00, ~5 Min.)","Fahrt zur Station Seomyeon (~10 Min.)","Abholung Seomyeon (~09:15, ~5 Min.)","Fahrt zur Station Haeundae (~15 Min.)","Abholung Haeundae (~09:30, ~5 Min.)"],"_poi_meta":{"match":"transit_only","poi_key":"OPS_busan_pickup_central","sources":["Visit Busan","Busan Metro"],"verified":true,"kb_version":"1.15","verified_date":"2026-04-29"},"highlights":["Drei Abholoptionen im zentralen Busan (Bahnhof Busan, Seomyeon, Haeundae)","Kleingruppen-Bus (max. ~14 Pers.)","Gesamtfahrzeit zum ersten Stopp: ~30-40 Min.","Gedruckte koreanisch-englische Programmkarte wird bei der Abholung verteilt"],"whyOnRoute":"Drei Abholpunkte decken Busans drei wichtigste Hotelzonen ab (KTX/Nampo, Seomyeon-Innenstadt, Haeundae-Strand), ohne dass Gäste morgens quer durch die Stadt fahren müssen. Die Reihenfolge Nordwest→Ost minimiert die Busstrecke und bringt die Gruppe gegen 10:00 zum Haedong-Yonggungsa-Tempel — früh genug, um den stärksten Reisebus-Ankünften zuvorzukommen.","description":"Die Abholung ist an drei zentralen Verkehrsknotenpunkten Busans gebündelt, damit der Tag ohne Kreuz-und-quer-Fahrten durch die Stadt planbar bleibt: **Bahnhof Busan (Linie 1)** für Gäste nahe dem KTX-Terminal oder im Viertel Choryang/Nampo-dong; **Station Seomyeon (Linien 1 & 2)** — Busans verkehrsreichster U-Bahn-Umsteigepunkt, zentral für Gäste in Innenstadthotels rund um das Lotte Hotel Busan oder die Seomyeon Medical Street; und **Station Haeundae (Linie 2)** für Gäste im Strandresort-Viertel nahe Westin Josun, Park Hyatt oder Signiel Busan. \n\nDer Bus holt an allen drei Punkten der Reihe nach ab (typischerweise zuerst Bahnhof Busan ~09:00, Seomyeon ~09:15, Haeundae ~09:30) und fährt dann über die Küstenroute der Gwangan-Brücke nordostwärts nach Gijang-gun zum ersten Stopp des Tages. \n\nGesamtfahrzeit von der letzten Abholung bis zum Haedong-Yonggungsa-Tempel: ~30-40 Minuten je nach Verkehr. Der Fahrer verteilt eine gedruckte koreanisch-englische Programmkarte mit Zeitangaben; bitte seien Sie 5 Minuten vor der geplanten Zeit an Ihrem Abholpunkt, damit der Tag für die späteren Dorfstopps in Gamcheon und Dakbatgol im Zeitplan bleibt.","_role":"pickup"},{"name":"Haedong-Yonggungsa-Tempel","time":"≈ 10:00","number":2,"category":"Buddhistischer Tempel / Küste","duration":"75 Min.","timeUsed":["Ausstieg aus dem Bus + Gang durch die Händlergasse zum Eingangsplatz (~10 Min.)","Zwölf Tierkreis-Generäle + „Unfallfrei-Pagode“ (~10 Min.)","Abstieg über die 108 Stufen + Haupthalle Daeungjeon + Meeresterrassen (~30 Min.)","Aussichtspunkt der Haesu-Gwaneum-Statue + Fotozeit (~15 Min.)","Rückweg hinauf + Sammeln am Bus (~10 Min.)"],"_poi_meta":{"match":"exact","poi_key":"haedong_yonggungsa","sources":["Visit Busan","VisitKorea","Wikipedia","Culture Trip","Korean Temple Guide","Korea Tourism Organization Official"],"verified":true,"kb_version":"1.24","verified_date":"2026-04-29"},"highlights":["**Gegründet 1376** vom buddhistischen Meister Naong Hyegeun (ursprünglich „Bomunsa“)","Einer der ganz wenigen bedeutenden koreanischen Tempel direkt am Meer (die meisten liegen in den Bergen)","**1974 in Haedong Yonggungsa umbenannt** nach der Drachen-Göttinnen-Vision von Mönch Jeong-am","**108 Steinstufen** = die 108 Verblendungen des Geistes im Buddhismus","**12 Sibiji-shin (Tierkreis-Generäle)** am Eingang; Münzschrein der „**Unfallfrei-Pagode**“","**Haesu Gwaneum Daebul** (Meeresgöttin der Barmherzigkeit) — der meistfotografierte Klippenblick","Haupthalle Daeungjeon 1970 mit Blick auf die Originalfarben restauriert","Täglich 04:30-19:20 geöffnet, EINTRITT FREI; Laternenfest zu Buddhas Geburtstag (Mai)","**Steinsäulen-Aufstellung der 12 buddhistischen Sibiji-shin-Tierkreis-Generäle am Tempeltor** — einzigartig unter Koreas Küstentempeln"],"smartNotes":{"tip":"Hallen durch die Seitentüren betreten (die Vordertür ist den Mönchen vorbehalten); zu Buddhas Geburtstag (Apr.–Mai) leuchtet die Laterneninstallation; kommen Sie vor 10:30, um den größten Reisebus-Andrang zu vermeiden","photo":"Der Sonnenaufgangsfelsen am seewärtigen Rand; die Treppe neben der Daeungjeon-Halle liefert das klassische Motiv aus Meer und Tempel; die Haesu-Gwaneum-Statue von der oberen Klippe gibt den Weitwinkelblick auf Tempel und Ostmeer","facilities":"Souvenir- und Snackstände sowie ein kleines Café am oberen Platz; ein Küstenpfad führt weiter über die Felsen"},"whyOnRoute":"**Der ikonische Auftakt der Route — Busans meistfotografierter Tempel in seinem ruhigen Fenster.** Die Ankunft um 10:00 liegt vor dem großen Ansturm der Reisebusse (typischerweise ab 11:00), sodass der Abstieg über die 108 Stufen und der Aussichtspunkt der Haesu-Gwaneum-Statue noch ohne Anstehen begehbar sind. Die Klippenlage in Gijang setzt den Tagesbeginn zudem an den äußersten Nordostpunkt der Route, sodass alles Weitere in eine Richtung die Küste hinabfließt — als Nächstes Cheongsapo, dann die Kapselfahrt Richtung Stadt — ganz ohne Zurückfahren.","convenience":{"parking":"Parkplatz Haedong Yonggungsa (kostenpflichtig, laut Visit Busan)","restroom":"Nahe dem Haupteingang und innerhalb der Anlage vorhanden"},"description":"**Haedong Yonggungsa (해동 용궁사) — Koreas berühmtester buddhistischer Tempel am Meer** — thront auf den Felsklippen von Gijang-gun an Busans Nordostküste, einer der ganz wenigen bedeutenden koreanischen Tempel, die NICHT in den Bergen liegen. Ursprünglich gegründet **1376 während der Goryeo-Dynastie durch den großen buddhistischen Lehrer Naong Hyegeun (나옹 혜근, 1320-1376)** — königlicher Berater und Meister, der den koreanischen Buddhismus bis in die frühe Joseon-Ära prägen sollte. \n\nDer Legende nach übte Naong während einer landesweiten Dürre Askese im Bunhwangsa-Tempel in Gyeongju; der Gott des Ostmeers erschien ihm im Traum und verkündete, dass der Bau eines Tempels auf dem Bongrae-Berg (dem ursprünglichen Namen dieser Küstenklippe) den Wohlstand des Königreichs wiederherstellen würde. \n\nNaong gründete den Tempel und nannte ihn **Bomunsa**, geweiht Gwanseum-bosal (관세음보살, dem Bodhisattva des Mitgefühls). Der Tempel wurde in der **japanischen Imjin-Invasion von 1592** zerstört und lag über 300 Jahre in Ruinen, bis **Mönch Ungang vom Tongdosa-Tempel in den frühen 1930er-Jahren mit dem Wiederaufbau begann**. \n\nDer heutige Name, **Haedong Yonggungsa (Koreanischer Drachenpalast-Tempel)**, stammt erst von **1974** — als Vorsteher Jeong-am während eines 100-tägigen Gebets (jeong-geon kido) eine Vision der Göttin der Barmherzigkeit hatte, die auf dem Rücken eines Drachen herabstieg und vielfarbiges Licht ausstrahlte. \n\nZu Ehren dieser Vision wurde der Tempel umbenannt. Der Besuch folgt dem charakteristischen Prozessionsweg des Tempels: durch die Reihe der **12 Sibiji-shin (Zwölf Tierkreis-Generäle)** am Eingangsplatz, vorbei an der **7-stöckigen „Unfallfrei-Pagode“** (wo Autofahrer Münzopfer unter einem steinernen Radschrein hinterlassen), die berühmten **108 Steinstufen** hinab (sie stehen für die 108 Verblendungen des buddhistischen Geistes) durch einen kleinen Bambushain und hinaus auf die Meeresterrassen und zur Haupthalle Daeungjeon. \n\nDie **Haesu Gwaneum Daebul** (Statue der Meeresgöttin der Barmherzigkeit) auf der oberen Klippe ist der meistfotografierte Blick und rahmt sowohl die Tempeldächer als auch das Ostmeer. \n\nÖffnungszeiten **täglich 04:30-19:20, letzter Einlass 18:50, EINTRITT FREI**. Zu **Buddhas Geburtstag (Mai)** erstrahlt das Laternenfest Yeondunhoe.","visitBasics":{"hours":"Täglich 04:30–19:20 (letzter Einlass 18:50)","closed":"Ganzjährig geöffnet","walking":"Moderat — 108 Stufen durch einen Kiefernhain, mehrere Meeresterrassen und Treppen","admission":"Frei; Parken für Privatwagen kostenpflichtig"},"image":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","images":["/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-haesu-gwaneum.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-dragon-hall.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-main-courtyard.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-zodiac-statues.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp"],"imageCredits":[{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-haesu-gwaneum.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-dragon-hall.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-main-courtyard.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-zodiac-statues.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 1","alt":"Haedong Yonggungsa Temple — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-haesu-gwaneum.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 2","alt":"Haedong Yonggungsa Temple — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-dragon-hall.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 3","alt":"Haedong Yonggungsa Temple — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-main-courtyard.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 4","alt":"Haedong Yonggungsa Temple — gallery image 4"},{"id":5,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-zodiac-statues.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 5","alt":"Haedong Yonggungsa Temple — gallery image 5"},{"id":6,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 6","alt":"Haedong Yonggungsa Temple — gallery image 6"}]},{"number":3,"time":"≈ 11:45","duration":"40 Min.","name":"Cheongsapo-Daritdol-Observatorium (Glas-Skywalk)","category":"Küsten-Observatorium / Kostenlos","description":"Das **Cheongsapo-Daritdol-Observatorium (청사포 다릿돌전망대)** ist ein **72,5 Meter langer Skywalk, der sich etwa 20 Meter über dem Wasser aufs Meer hinausschwingt**, eröffnet im August 2017 auf der Küstenklippe zwischen Cheongsapo und Songjeong. Sein Name kommt von den **daritdol — den fünf „Trittstein“-Rifffelsen**, die unter dem Steg im Meer liegen und der Sage nach wie eine Brücke zum Horizont schreiten. Der äußere Abschnitt des Stegbodens ist aus **Glas**, mit gestellten Schuhüberziehern zum Schutz der Scheiben (und als Vertrauensbeweis!), während die Dünung unter Ihren Füßen rollt. Der Eintritt ist **frei**. Zurück im Dorf sind die **Zwillingsleuchttürme von Cheongsapo** (einer rot, einer weiß) und der kleine Bahnübergang, den sein Anime-Bildausschnitt im Slam-Dunk-Stil berühmt gemacht hat, nur einen kurzen Spaziergang entfernt.","image":null,"highlights":["**72,5-m-Skywalk, ~20 m über dem Meer** — eröffnet August 2017, KOSTENLOS","Benannt nach den fünf **daritdol-„Trittstein“-Riffen**, die unter dem Steg sichtbar sind","**Glasboden-Abschnitt** am seewärtigen Ende (Schuhüberzieher werden gestellt)","**Zwillingsleuchttürme von Cheongsapo** (rot + weiß), einen kurzen Spaziergang entfernt","Cheongsapo zählt zu Busans **acht schönsten Aussichten** — ein aktives Fischerdorf","Anime-berühmter Bahnübergang als Fotospot"],"timeUsed":["Ausstieg aus dem Bus + Fußweg zum Skywalk-Eingang (~5 Min.)","Gang auf den Skywalk + Glasboden-Abschnitt (~20 Min.)","Spaziergang zu Zwillingsleuchttürmen / Bahnübergang für Fotos (~10 Min.)","Sammeln für die Kapselstation (~5 Min.)"],"whyOnRoute":"**Der kostenlose Nervenkitzel zwischen Tempel und Kapsel.** Daritdol gibt dem Tag seinen Moment über dem Meer — ein Glasboden mit rollender Dünung darunter — ganz ohne Ticket, und es liegt direkt auf der Cheongsapo-Klippe, sodass es nahtlos in das nur Minuten entfernte Einsteigen in die Sky Capsule übergeht. Wer die Küste zuerst vom feststehenden Skywalk aus gesehen hat, erlebt den Blick aus der fahrenden Kapsel zehn Minuten später ganz anders.","_poi_meta":{"match":"authored","poi_key":"cheongsapo_daritdol_observatory","sources":["Visit Busan","Busan Metropolitan City Tourism","Blue Line Park official"],"verified":false,"verified_date":"2026-08-04"},"smartNotes":{"tip":"An windigen Tagen schließt der Steg gelegentlich — der Guide prüft die Bedingungen und ordnet das Cheongsapo-Ensemble bei Bedarf um","photo":"Fotografieren Sie durch das Glas hinab auf die daritdol-Riffe; die Kurve des Stegs vom Uferweg aus ergibt die beste Weitaufnahme","facilities":"Cafés und Fischstände im Dorf Cheongsapo unterhalb"},"convenience":{"parking":"Bushalt im Dorf Cheongsapo; kurzer Fußweg zum Steg","restroom":"Öffentliche Toiletten nahe der Station Cheongsapo"},"visitBasics":{"hours":"Frei zugänglich; Observatorium besetzt etwa 09:00–18:00 (saison-/wetterabhängig)","closed":"Kann bei starkem Wind oder Sturm vorübergehend schließen","walking":"Ebener Gang auf dem Steg; eine kurze Steigung vom Dorf","admission":"KOSTENLOS (Schuhüberzieher für den Glasabschnitt werden gestellt)"},"images":[],"imageCredits":[],"galleryItems":[]},{"number":4,"time":"≈ 12:35","duration":"40 Min.","name":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo)","category":"Küstenfahrt / Ticket optional","description":"Die **Sky Capsule** ist die Signature-Fahrt des **Haeundae Blueline Park**, der 2020 eröffneten Öko-Umnutzung der stillgelegten Donghae-Nambu-Küstenbahn: **pastellfarbene 4-Sitzer-Kabinen, die 2,3 km auf einer aufgeständerten Trasse 7–10 Meter über der Küstenlinie** zwischen Cheongsapo und Mipo gleiten, mit dem Meer die ganze Zeit auf einer Seite (~30 Minuten). Wir steigen in **Cheongsapo ein und fahren Richtung Mipo**, wo der Bus bereits wartet — die Fahrt dient also zugleich als Tagestransfer die Küste hinab. **Das Kapselticket ist optional und wird bei der Buchung gewählt**: Mit der Option „Ticket inbegriffen“ reservieren wir die Kapseln für Ihre Gruppe vorab (Preis pro Kapsel: etwa ₩30,000 für 2 / ₩39,000 für 3 / ₩44,000 für 4, einfache Fahrt); mit der Basisoption können Sie über den **kostenlosen Green-Railway-Holzsteg** gehen — die preisgekrönte 2,3 km lange hölzerne Uferpromenade unter derselben Trasse — oder einfach mit dem Bus nach Mipo fahren.","image":"/images/tours/cheongsapo-blue-line/cheongsapo-sky-capsule-interior.webp","highlights":["**Pastellfarbene 4-Sitzer-Kapseln auf einer aufgeständerten Küstentrasse** — die Signature-Fahrt des Blueline Park (eröffnet 2020)","**Cheongsapo → Mipo, 2,3 km / ~30 Min.**, Meerblick auf der ganzen Strecke","**Ticket inbegriffen oder nicht — Ihre Wahl bei der Buchung** (Preis pro Kapsel ≈ ₩30,000 für 2 / ₩39,000 für 3 / ₩44,000 für 4, einfache Fahrt)","Nicht-Mitfahrende: **kostenloser Green-Railway-Holzsteg** (Uferpromenade) entlang derselben Küste oder der Bus nach Mipo","Die Fahrt endet, wo das Mittagessen beginnt — Mipo liegt nur einen kurzen Fußweg von Haeundaes Essensstraßen entfernt","Fährt bei normalem Regen; pausiert nur bei starkem Wind"],"timeUsed":["Einstieg an der Station Cheongsapo (~10 Min.)","Fahrt mit der Sky Capsule Cheongsapo → Mipo (~30 Min.)"],"whyOnRoute":"**Die Fahrt, die zugleich der Transfer ist.** Der Einstieg in Cheongsapo direkt nach dem Skywalk bedeutet, dass die Kapsel Sie genau die Küste hinabträgt, über die Sie gerade geblickt haben — und sie setzt Sie in Mipo ab, wo Bus und Essensstraßen bereits warten. Nichts am Tag macht dafür einen Umweg: Lassen Sie das Ticket aus, decken der Bus oder die kostenlose Uferpromenade dieselbe Etappe ab.","_poi_meta":{"match":"partial","poi_key":"cheongsapo_blue_line_park","sources":["Blue Line Park official","Visit Busan","Busan Metropolitan City Tourism"],"verified":true,"kb_version":"1.24","verified_date":"2026-08-04"},"smartNotes":{"tip":"Sonnenuntergangs- und Wochenendtermine sind 1–2 Wochen im Voraus ausverkauft — wählen Sie bei der Buchung die Option mit inbegriffenem Ticket, und wir reservieren für Sie","photo":"Setzen Sie sich auf die Meerseite (in Fahrtrichtung Mipo rechts); die Kurve am Dalmaji-Tunnel ist das Signature-Motiv","facilities":"Cafés und Convenience-Store am Vorplatz von Mipo; Ticketautomaten an beiden Stationen"},"convenience":{"parking":"Der Bus trifft die Gruppe am Stationsvorplatz von Mipo","restroom":"An beiden Stationen, Cheongsapo und Mipo"},"visitBasics":{"hours":"≈ 09:30–18:30 (in der Hochsaison bis in den Abend verlängert)","closed":"Wetterabhängig; starker Wind pausiert den Betrieb","walking":"Ebene Bahnsteige; die Alternative über den Holzsteg beträgt 2,3 km (~30 Min.) auf Holzplanken","admission":"Pro Kapsel, einfache Fahrt: ≈ ₩30,000 (2 Pers.) / ₩39,000 (3) / ₩44,000 (4) — Option mit inbegriffenem Ticket bei der Buchung verfügbar"},"images":["/images/tours/cheongsapo-blue-line/cheongsapo-sky-capsule-interior.webp","/images/tours/cheongsapo-blue-line/blueline-tram-cherry-sea.webp","/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-01-01-18.webp","/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-12-53-19.webp"],"imageCredits":[{"url":"/images/tours/cheongsapo-blue-line/cheongsapo-sky-capsule-interior.webp","source":"atoc-korea"},{"url":"/images/tours/cheongsapo-blue-line/blueline-tram-cherry-sea.webp","source":"atoc-korea"},{"url":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-01-01-18.webp","source":"atoc-korea"},{"url":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-12-53-19.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/cheongsapo-blue-line/cheongsapo-sky-capsule-interior.webp","location":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo)","caption":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — photo 1","alt":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/cheongsapo-blue-line/blueline-tram-cherry-sea.webp","location":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo)","caption":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — photo 2","alt":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-01-01-18.webp","location":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo)","caption":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — photo 3","alt":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-12-53-19.webp","location":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo)","caption":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — photo 4","alt":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — gallery image 4"}]},{"name":"Mittagessen (lokales Restaurant nahe Haeundae/Mipo)","time":"≈ 13:25","number":5,"category":"Lokale Mahlzeit","duration":"60 Min.","timeUsed":["Fußweg von der Station Mipo zum Restaurant (~5 Min.)","Mittagessen (~50 Min.)","Sammeln am Bus (~5 Min.)"],"_poi_meta":{"match":"lunch_placeholder","poi_key":"OPS_busan_lunch","sources":["Visit Busan","Busan Metropolitan Government cuisine guide"],"verified":true,"kb_version":"1.15","verified_date":"2026-04-29"},"highlights":[],"whyOnRoute":"**Die natürliche Pause zwischen Küste und Dörfern.** Die Kapselfahrt endet zur Mittagszeit in Mipo, und Haeundaes Essensstraßen sind nur einen kurzen Fußweg von der Station entfernt — keine zusätzliche Fahrt für eine gute Mahlzeit. Wer sich hier stärkt, ist bereit für die beiden Hangdörfer des Nachmittags, wo das Gehen am steilsten wird.","description":"Etwa 60 Minuten Mittagspause nahe Mipo/Haeundae, direkt nachdem die Sky Capsule angekommen ist. Typische Empfehlungen des Guides: **dwaeji-gukbap (돼지국밥)** — Busans typische Reissuppe mit Schweinefleischbrühe, entstanden in der Flüchtlingszeit des Koreakriegs (~₩10,000), **milmyeon**, kalte Weizennudeln, oder ein Fischrestaurant am Hafen. Das Mittagessen ist nicht inbegriffen (≈ ₩10,000–15,000), sodass Sie nach Appetit und Budget wählen können."},{"name":"Kulturdorf Gamcheon","time":"≈ 15:00","number":6,"category":"Kulturdorf / Wandmalerei-Kunst","duration":"90 min","timeUsed":["Ausstieg aus dem Bus am öffentlichen Parkplatz 2 + Fußweg zum Eingang (~5 Min.)","Touristeninformation + Kauf der Stempelkarte (~10 Min.)","Aussichtspunkt Sky Garden + Bank des Kleinen Prinzen (~25 Min.)","Gassenspaziergang vorbei an Wandbildern + kleine Café-Pause (~25 Min.)","Sammeln am Bus (~10 Min.)"],"_poi_meta":{"match":"exact","poi_key":"gamcheon_culture_village","sources":["Wikipedia","CNN","Visit Busan","Hapskorea","Columban Society","Lifeguin","Busan Cultural Foundation"],"verified":true,"kb_version":"1.24","verified_date":"2026-04-29"},"highlights":["**„Koreas Machu Picchu“ / „Koreas Santorin“** — UN-HABITAT Asian Townscape Award 2012","Ursprünge: Umsiedlung durch die Busaner Verwaltung **1920er-1930er** + **Taegeukdo-Flüchtlinge 1955** (~800 Familien)","**Taegeukdo-Philosophie des „andere gedeihen Lassens“** = kein Haus verstellt die Sicht des dahinterliegenden","**2009 „Dreaming of Machu Picchu“ + 2010 „Miro Miro“** — Public-Art-Projekte des Kulturministeriums","**Bank mit dem „Kleinen Prinzen und dem Fuchs“** am Sky Garden — der meistfotografierte Ort des Dorfes","**~1,4 Millionen Besucher jährlich** seit der Public-Art-Erneuerung","**Bewohnte Wohngemeinschaft** — leise Stimmen, keine Drohnen, kein Blitzlicht in die Häuser","Freier Dorfeintritt; optionale Stempelkarte ~₩2,000","**UN-HABITAT Asian Townscape Award 2012** — Auszeichnung für das Kunstprojekt „Dreaming of Machu Picchu“ von 2009, das die Taegeukdo-Flüchtlingssiedlung von 1955 in Busans bekanntestes Wandmalereidorf verwandelte"],"smartNotes":{"tip":"Hier leben Menschen — sprechen Sie leise, keine Drohnen, nehmen Sie Abfall mit; tragen Sie rutschfeste Schuhe für die steilen Gassen; die goldene Stunde am Nachmittag ~16:00-17:00 ist das schönste Licht des Dorfes","photo":"Bank mit dem Kleinen Prinzen und dem Fuchs (lange Schlange) und Haneul Maru / Sky-Garden-Observatorium für den weiten Blick auf Regenbogendächer und Bucht","facilities":"Hanbok-Verleih, Handwerksateliers, koreanische Süßigkeitenstände, Cafés; kleines Dorfmuseum am Eingang; die Stempelkarte ist der einfachste Wegweiser"},"whyOnRoute":"**Das Hauptdorf des Nachmittags — Busans Pastell-Amphitheater.** Nach dem Küstenmorgen wechselt der Tag zu den westlichen Hanglagen, wo sich Gamcheons Flüchtlingsterrassen aus der Koreakriegszeit, 2009 als Kunstdorf wiedergeboren, in Bonbonfarben über dem Meer stapeln. Die 90-minütige Runde umfasst die Aussichtspunkte, den Sims mit dem Kleinen Prinzen und Zeit zum Streifen durch die Gassen — und sie ist bewusst mit dem stillen Dakbatgol direkt danach kombiniert, damit Sie sowohl das berühmte Dorf als auch das lokale sehen, das die Busse auslassen.","convenience":{"parking":"Öffentlicher Parkplatz Gamcheon 2 (kostenpflichtig)","restroom":"Öffentliche Toiletten an der Touristeninformation und an den Hauptaussichtspunkten"},"description":"Das **Kulturdorf Gamcheon (감천문화마을)** — genannt sowohl **„Koreas Machu Picchu“** als auch **„Koreas Santorin“** — ist ein Hangviertel in Saha-gu im Westen Busans, dessen pastellfarben gestrichene Häuser in gestaffelten Reihen den Hang hinabfallen. \n\nDie Siedlung entstand in den **1920er-1930er-Jahren**, als die Busaner Verwaltung Arbeiterfamilien vom Hafen weg umsiedelte. Ihren Charakter erhielt das Dorf **1955**, als sich **~800 Familien (etwa 4.000 Menschen) der Taegeukdo-Glaubensgemeinschaft** — einer einzigartig koreanischen synkretistischen Religion, die buddhistische, konfuzianische und Yin-Yang-Elemente verbindet, gegründet von **Jo Cheol-je** während der japanischen Kolonialzeit — hier als Koreakriegsflüchtlinge aus dem Norden niederließen. \n\nDie Taegeukdo-Philosophie, „**andere gedeihen zu lassen**“, prägte unmittelbar das markanteste Merkmal des Dorfes: Die Häuser sind bewusst so gestaffelt, dass **kein Dach dem Haus dahinter die Sicht nimmt** — die ganze Gemeinschaft bleibt zu Himmel und Meer hin offen. Gamcheon blieb eines der ärmsten Viertel Busans, bis das koreanische Kulturministerium **2009** das Public-Art-Projekt **„Dreaming of Machu Picchu in Busan“** startete, gefolgt vom **„Miro Miro“-Projekt (Labyrinth) 2010** — mit über 22 beauftragten Wandbildern, Skulpturen und Kunstinstallationen, darunter die ikonische **Bank mit dem „Kleinen Prinzen und dem Fuchs“** am Aussichtspunkt Sky Garden. \n\nGamcheon gewann den **UN-HABITAT Asian Townscape Award 2012** und empfängt heute **~1,4 Millionen Besucher jährlich**. Der Besuch folgt der charakteristischen Stempelkarten-Route des Dorfes: vom Eingang an der **Touristeninformation** hinauf zum **Aussichtspunkt Sky Garden** für das Panorama der Regenbogendächer, dann hinab durch die labyrinthischen Gassen vorbei an Wandbildern, Hanbok-Verleihen, Handwerksateliers und kleinen Cafés. \n\n**Das Dorf ist eine bewohnte Wohngemeinschaft** — leise Stimmen sind Pflicht, keine Drohnen, kein Blitzlicht in die Häuser, und Abfall wird mitgenommen. \n\nÖffnungszeiten **09:00-18:00 März-Okt. / 09:00-17:00 Nov.-Feb. (Infozentrum)**; **das Dorf selbst ist rund um die Uhr geöffnet, EINTRITT FREI**.","visitBasics":{"hours":"Täglich 09:00–18:00 (März–Okt.) / 09:00–17:00 (Nov.–Feb.); manche Läden/Cafés haben eigene Öffnungszeiten","closed":"Ganzjährig geöffnet (eine bewohnte Wohngemeinschaft)","walking":"Anstrengend — sehr steile Gassen und Treppen; in vielen Abschnitten nicht kinderwagen- oder rollstuhlgerecht","admission":"Freier Dorfeintritt; optionale Stempelkarte ≈ 2,000 KRW"},"image":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","images":["/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","/images/tours/gamcheon-culture-village/chatgpt-image-2026-5-11-01-00-53.webp","/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","/images/tours/gamcheon-culture-village/gamcheon-little-prince-day-sign.webp"],"imageCredits":[{"url":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/chatgpt-image-2026-5-11-01-00-53.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-day-sign.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 1","alt":"Gamcheon Culture Village — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/gamcheon-culture-village/chatgpt-image-2026-5-11-01-00-53.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 2","alt":"Gamcheon Culture Village — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 3","alt":"Gamcheon Culture Village — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-day-sign.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 8","alt":"Gamcheon Culture Village — gallery image 8"}]},{"number":7,"time":"≈ 16:50","duration":"50 Min.","name":"Dakbatgol-Wandmalereidorf & Monorail an der „Wunschtreppe“","category":"Wandmalereidorf / Kostenlose Monorail","description":"**Dakbatgol (닥밭골)** ist ein Hangdorf in Busans Bezirk Seo-gu, dessen Name an die **Papiermaulbeer-Felder (dak)** erinnert, die einst Koreas traditionelle Hanji-Papiermacher belieferten. Wie Gamcheon klettert es in engen Gassen einen steilen Hang hinauf — doch es wurde nie zum Reisebus-Stopp, sodass seine **Wandmalerei-Gassen, Hanji-Motive und Aussichtspunkte still und lokal bleiben**, Wäscheleinen inklusive. Das Wahrzeichen des Dorfes ist die **„Wunschtreppe“ (소망계단)** — eine lange, steile, mit Wandmalereien bemalte Treppenstraße — und die **kostenlose Standseil-Monorail**, die daneben hinaufgleitet, installiert, damit die älteren Bewohner ihre Häuser erreichen können; auch Besucher fahren mit und verwandeln so den steilsten Anstieg des Nachmittags in einen Aussichtspunkt in Zeitlupe. Es ist der bewusst menschliche Kontrapunkt zu Gamcheons Ruhm, zehn Minuten vor der Ausstiegszone.","image":null,"highlights":["**Stilles Wandmalereidorf** — Gamcheons lokales Gegenstück, fast ohne Menschenmengen","Benannt nach den **Papiermaulbeer-Feldern (dak)** von Busans Hanji-Papiererbe","**„Wunschtreppe“ (소망계단)** — eine steile Treppenstraße voller Wandmalereien","**Kostenlose Standseil-Monorail** neben der Treppe — für die Dorfältesten gebaut, offen für Besucher","Hang-Aussichtspunkte über das alte Hafenviertel","EINTRITT FREI; ein wirklich bewohntes Viertel — bitte leise sprechen"],"timeUsed":["Ausstieg aus dem Bus + Spaziergang durch die Wandmalerei-Gassen (~20 Min.)","Monorail-Fahrt die „Wunschtreppe“ hinauf + Aussichtspunkt (~15 Min.)","Abstieg + Fotozeit (~10 Min.)","Sammeln am Bus (~5 Min.)"],"whyOnRoute":"**Der stille Abschluss, den die Busse auslassen.** Nach Gamcheons Menschenmengen zeigt Dakbatgol dasselbe Hang-Busan in Alltagslautstärke — Wandmalereien, die „Wunschtreppe“ und eine Monorail, die den Aufstieg übernimmt. Es schließt das Dörfer-Kapitel zehn Minuten von der Nampo-Ausstiegszone entfernt, sodass der Tag tief in lokaler Atmosphäre endet statt im Verkehr.","_poi_meta":{"match":"authored","poi_key":"dakbatgol_mural_village","sources":["Visit Busan","Busan Seo-gu Office"],"verified":false,"verified_date":"2026-08-04"},"smartNotes":{"tip":"Dies ist ein bewohntes Dorf, kein Themenpark — sprechen Sie in den Gassen leise und fotografieren Sie nicht in offene Türen","photo":"Fotografieren Sie die „Wunschtreppe“ von unten mit der daneben verlaufenden Monorail-Trasse; der obere Aussichtspunkt rahmt das Hafenviertel","facilities":"Kleine Cafés nahe dem Eingang; mehr Auswahl in Nampo-dong nach dem Ausstieg"},"convenience":{"parking":"Bushalt am Dorfeingang","restroom":"Öffentliche Toilette nahe dem Dorfeingang"},"visitBasics":{"hours":"Offenes Dorf; die Monorail fährt tagsüber (≈ 09:00–18:00, wetterabhängig)","closed":"Die Monorail kann für Wartung oder bei Sturm pausieren — die Treppe bleibt offen","walking":"Steile Gassen und Treppen; die Monorail deckt den steilsten Abschnitt ab","admission":"KOSTENLOS (Dorf und Monorail)"},"images":[],"imageCredits":[],"galleryItems":[]},{"number":8,"time":"≈ 17:50","duration":"≈ 70 Min. gesamt","name":"Ausstieg (4 Punkte im zentralen Busan)","category":"Ausstieg — Zentrale Stationen der Reihe nach","description":"**Die Ausstiege erfolgen der Reihe nach von der Westseite zurück nach Osten**: **Nampo-dong / Jagalchi-Viertel (~17:50)** — steigen Sie hier aus für Busans beste abendliche Essensstraßen und das nächtliche Treiben am BIFF Square; **Bahnhof Busan (~18:10)** für KTX-Anschlüsse; **Seomyeon (~18:30)** für das zentrale Hotelviertel; und **Haeundae (~19:00)** zuletzt. Wählen Sie Ihren Ausstiegspunkt im Laufe des Nachmittags mit dem Guide — bis Haeundae sitzen zu bleiben ist die längste Fahrt, bringt Sie aber für den Abend direkt an den Strand.","image":null,"highlights":[],"timeUsed":["Nampo-dong / Jagalchi-Viertel (~17:50)","Bahnhof Busan (~18:10)","Seomyeon (~18:30)","Haeundae (~19:00)"],"whyOnRoute":"Dakbatgol liegt zehn Minuten von Nampo-dong entfernt, sodass die Ausstiegssequenz fast unmittelbar nach dem letzten Stopp beginnt — keine tote Transferzeit. Die West-nach-Ost-Reihenfolge spiegelt die morgendlichen Abholungen und deckt KTX-Reisende (Bahnhof Busan), zentrale Hotels (Seomyeon) und Strandhotels (Haeundae) ohne Zurückfahren ab.","_poi_meta":null,"images":[],"imageCredits":[],"galleryItems":[]}]}},{"id":"day_flow","section_html_id":null,"component":"TourDayFlowSection","props":{"routeFlowStops":[{"name":"Abholung (3 zentrale Stationen in Busan)","type":"origin","theme":"Departure"},{"name":"Haedong-Yonggungsa-Tempel","type":"primary","theme":"Seaside temple"},{"name":"Cheongsapo-Daritdol-Observatorium (Glas-Skywalk)","type":"secondary","theme":"Glass Skywalk"},{"name":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo)","type":"primary","theme":"Sky Capsule"},{"name":"Mittagessen (lokales Restaurant in Busan)","type":"meal","theme":"Meal"},{"name":"Kulturdorf Gamcheon","type":"primary","theme":"Art village"},{"name":"Dakbatgol-Wandmalereidorf & Monorail an der „Wunschtreppe“","type":"secondary","theme":"Mural Village"},{"name":"Ausstieg (4 Punkte im zentralen Busan)","type":"return","theme":"Return"}],"routePhases":[{"phase":"Küstenmorgen","duration":"≈ 3 Stunden","description":"Abholung an drei zentralen Stationen (08:30–09:30), dann der Haedong-Yonggungsa-Tempel vor dem Ansturm der Reisebusse und weiter zum Daritdol-Glas-Skywalk in Cheongsapo."},{"phase":"Sky Capsule + Mittagessen","duration":"≈ 2 Stunden","description":"Die Pastellfahrt mit der Sky Capsule von Cheongsapo nach Mipo (Ticket optional — wer nicht mitfährt, nimmt den Bus oder geht über den Green-Railway-Holzsteg, die Uferpromenade), danach Mittagessen nahe Haeundae."},{"phase":"Zwei Hangdörfer","duration":"≈ 3 Stunden","description":"Die Foto-Runde durch das Kulturdorf Gamcheon (90 Min.), dann das stille Dakbatgol-Wandmalereidorf mit seiner kostenlosen Monorail an der „Wunschtreppe“ (50 Min.)."},{"phase":"Zentraler Abschluss","duration":"≈ 1 Stunde","description":"Ausstiege der Reihe nach: Nampo-dong, Bahnhof Busan, Seomyeon, dann Haeundae."}],"routeShapeIntro":{"title":"So bewegt sich dieser Busan-Tag","subtitle":"Zuerst die Ostküste: der Tempel am Meer in seinem ruhigen Morgenfenster, dann das Cheongsapo-Ensemble — Glas-Skywalk, Zwillingsleuchttürme — wo die Fahrt mit der Sky Capsule selbst zum Transfer die Küste hinab nach Mipo wird. Nach dem Mittagessen wechselt der Tag zu Busans westlichen Hanglagen für zwei Dörfer in zwei Stimmungen: Gamcheons weltberühmte Farben, dann Dakbatgols stille Wandmalereien, wo eine kostenlose Monorail die „Wunschtreppe“ hinaufgleitet. Zentrale Ausstiegspunkte schließen die Runde, von 08:30 bis etwa 18:30."}}},{"id":"details","section_html_id":"details","component":"TourFitSection","props":{"whyTourWorks":{"bestFor":["Erstbesucher in Busan","Paare und fotobegeisterte Reisende","Erwachsene Familien und Freundesgruppen","Reisende, die Küste UND Dörfer an einem Tag erleben möchten"],"lessIdealFor":["Reisende, die möglichst wenig gehen oder keine Steigungen möchten","Gruppen mit Kinderwagen (Dorfgassen und Treppen)","Nachtpanorama-Fans — dies ist eine Tagesroute"],"routeLogicSections":[{"title":"Pacing & geography","icon":"route","iconBg":"bg-sky-50/80","iconColor":"text-sky-600","items":[{"label":"Der Tempel in seinem ruhigen Fenster","detail":"Haedong Yonggungsa ist Busans meistfotografierter Tempel, und der Ansturm der Reisebusse beginnt gegen 11:00. Die Ankunft gegen 10:00 hält den Abstieg über die 108 Stufen und den Aussichtspunkt der Haesu-Gwaneum-Statue ohne Anstehen begehbar."},{"label":"Die Kapselfahrt IST der Transfer","detail":"Von Cheongsapo gleitet die pastellfarbene Sky Capsule 2,3 km die Küste hinab nach Mipo — die Fahrt ersetzt also eine Busetappe, statt einen Umweg hinzuzufügen. Gäste ohne Ticket fahren mit dem Bus nach Mipo oder gehen über den kostenlosen Green-Railway-Holzsteg (Uferpromenade) entlang derselben Küste."},{"label":"Zwei Hangdörfer, zwei Stimmungen","detail":"Gamcheon ist Busans weltberühmtes Pastell-Amphitheater; Dakbatgol, zehn Minuten entfernt, ist sein stilles lokales Gegenstück — Wandmalerei-Gassen fast ohne Menschenmengen, wo eine kostenlose Standseil-Monorail, gebaut für die älteren Dorfbewohner, Sie die „Wunschtreppe“ hinaufträgt."},{"label":"Eintrittsfreie Ankerpunkte, ein optionales Ticket","detail":"Yonggungsa, der Daritdol-Skywalk, Gamcheon und Dakbatgol (Monorail inbegriffen) sind alle kostenlos. Die einzige kostenpflichtige Attraktion des Tages ist die Sky Capsule — und Sie entscheiden bei der Buchung: Ticket inbegriffen, oder nicht inbegriffen, wenn Sie lieber die Uferpromenade entlanggehen."}]}]}}},{"id":"practical","section_html_id":null,"component":"TourPracticalDetails","props":{"practicalAccordionItems":[{"id":"pickup","title":"Abholung & Rückgabe","preview":"Drei Abholpunkte entlang der U-Bahn Busan: Seomyeon Station Ausgang 4 (08:30), Bahnhof Busan Ausgang 4 — nicht das KTX-Gate (08:50), Haeundae Station Ausgang 5 (09:30).","content":["Drei Abholpunkte entlang der U-Bahn Busan: Seomyeon Station Ausgang 4 (08:30), Bahnhof Busan Ausgang 4 — nicht das KTX-Gate (08:50), Haeundae Station Ausgang 5 (09:30).","Ausstiege in Reihenfolge: Nampo-dong/Jagalchi ≈17:50, Bahnhof Busan ≈18:10, Seomyeon ≈18:30, Haeundae ≈19:00.","Ihre effektive Tourdauer hängt vom Abholpunkt ab: Seomyeon ≈10 Std., Haeundae ≈9,5 Std."]},{"id":"what-to-bring","title":"Kleidung & Ausrüstung","preview":"Bequeme Wanderschuhe mit Profil — Gamcheons Hanggassen und Yonggungsas 108…","content":["Bequeme Wanderschuhe mit Profil — Gamcheons Hanggassen und Yonggungsas 108 Stufen verlangen beide Trittsicherheit.","Eine leichte Schicht für das klimatisierte Fahrzeug und die Meeresbrise am Yonggungsa.","Kamera oder Smartphone (Gamcheon und Cheongsapo sind die Foto-Höhepunkte).","Bargeld oder Karte für das Mittagessen (₩10,000–₩20,000), die optionalen Sky-Capsule-/Beach-Train-Tickets in Cheongsapo und das optionale Busan-Tower-Observatorium."]},{"id":"weather-policy","title":"Wetterregelung","preview":"Ganzjähriger Betrieb.","content":["Ganzjähriger Betrieb.","Leichter Regen: Die Tour läuft wie geplant — der Yonggungsa im Regen hat seine eigene Atmosphäre, und Gamcheons Gassen bleiben begehbar.","Starker Regen oder Sturm: Der Guide kann die Route anpassen, weil der untere Tempelbereich am Yonggungsa rutschig werden kann und Gamcheons Treppen unsicher sein können.","Wetter auf Taifun-Niveau: Volle Rückerstattung oder Umbuchung wird angeboten."]},{"id":"inclusions","title":"What''s included","preview":"Kleingruppen-Minibus (max. ≈12 Gäste), zertifizierter englischsprachiger Guide, Kraftstoff/Maut/Parken.","content":["Kleingruppen-Minibus (max. ≈12 Gäste), zertifizierter englischsprachiger Guide, Kraftstoff/Maut/Parken.","Alle Ankerattraktionen sind EINTRITTSFREI: Haedong Yonggungsa, Cheongsapo-Daritdol-Observatorium, Kulturdorf Gamcheon, Dakbatgol-Wandmalereidorf (Monorail an der „Wunschtreppe“ kostenlos).","Sky-Capsule-Ticket: bei der Buchung wählbar — inbegriffen (wir reservieren die Kapseln für Ihre Gruppe vorab; Basis: 2 Personen pro Kapsel) oder nicht inbegriffen (kostenloser Green-Railway-Holzsteg, die Uferpromenade, oder Busfahrt nach Mipo).","Nicht inbegriffen: Mittagessen (≈ ₩10,000–15,000), Getränke, persönliche Ausgaben, Trinkgelder."]},{"id":"language","title":"Sprache","preview":"Haupt-Toursprache: Englisch.","content":["Haupt-Toursprache: Englisch.","Chinesischsprachiger Guide auf Anfrage verfügbar — bitte mindestens 3 Tage im Voraus buchen.","Koreanisch begegnet Ihnen den ganzen Tag auf Speisekarten, Schildern und an Ständen; der Guide übernimmt die Übersetzung."]},{"id":"walking","title":"Walking & terrain","preview":"Mittlerer Schwierigkeitsgrad mit kurzen fordernden Abschnitten.","content":["Mittlerer Schwierigkeitsgrad mit kurzen fordernden Abschnitten.","Am Yonggungsa führen 108 Steinstufen hinab und wieder hinauf.","Der Daritdol-Skywalk ist eben (Glasboden, Schuhüberzieher werden gestellt).","Die Sky-Capsule-Stationen sind eben mit wenigen Bahnsteigstufen.","Gamcheon besteht aus Hanggassen und Treppen — tragen Sie bequeme Schuhe.","Dakbatgols „Wunschtreppe“ ist steil, doch die kostenlose Monorail übernimmt den Aufstieg.","Gesamtstrecke zu Fuß etwa 4–5 km."]},{"id":"capsule","title":"Sky Capsule (Ticket-Option)","preview":"Inbegriffen oder nicht — Ihre Wahl bei der Buchung.","content":["Die Sky Capsule fährt 2,3 km auf einer aufgeständerten Trasse zwischen Cheongsapo und Mipo (~30 Min.), in pastellfarbenen 4-Sitzer-Kabinen über der Küstenlinie.","Option mit Ticket: Wir reservieren die Kapseln für Ihre Gruppe vorab (Preis pro Kapsel ≈ ₩30,000 für 2 / ₩39,000 für 3 / ₩44,000 für 4, einfache Fahrt; die inbegriffene Option ist auf Basis von 2 Personen pro Kapsel kalkuliert).","Option ohne Ticket: Gehen Sie über den kostenlosen Green-Railway-Holzsteg (Uferpromenade, 2,3 km, ~30 Min., dieselbe Küste) oder fahren Sie mit dem Bus nach Mipo.","Der Betrieb ist wetterabhängig (starker Wind pausiert die Strecke); kann die Kapsel nicht fahren, halten der Weg über die Uferpromenade und der Bustransfer die Route im Zeitplan."]},{"id":"cancellation","title":"Stornierung","preview":"Kostenlose Stornierung bis 24 Stunden vor der Abholung.","content":["Kostenlose Stornierung bis 24 Stunden vor der Abholung.","Stornierungen am selben Tag und Nichterscheinen sind nicht erstattungsfähig."]}],"practicalWeatherStatic":{"today":{"temp":"—","label":"Siehe Saisonhinweise"},"tomorrow":{"temp":"—","label":"Siehe Saisonhinweise"},"_seasonalSummary":"Busan: Koreas südlichste Großstadt, milder und feuchter als Seoul. Milde Winter (5–10 °C), schwüle Sommer, meiste Niederschläge im Juli-Monsun."},"seasonalVariations":[{"season":"Frühling (März–Mai)","description":"Kirschblüten säumen die Blueline-Küste Ende März bis Anfang April — die Kapselfahrt zur Blütezeit ist die schönste des Jahres. Klare Tempelmorgen."},{"season":"Sommer (Juni–Aug.)","description":"Lange Tage, und die Küste bleibt kühler als die Innenstadt; der Juli-Monsun kann die Zeit auf dem Skywalk verkürzen. Die Kapsel fährt bis in den Abend hinein."},{"season":"Herbst (Sep.–Nov.)","description":"Der klarste Himmel des Jahres — beste Sicht vom Daritdol-Glasboden und die kräftigsten Farben an Gamcheons Aussichtspunkten."},{"season":"Winter (Dez.–Feb.)","description":"Die ruhigste Zeit an jedem Stopp; klares Licht für Fotos. Die Kapsel ist beheizt; ziehen Sie sich für die Tempelterrassen und Dorfgassen warm an."}]}},{"id":"booking_support","section_html_id":null,"component":"TourBookingSupportSection","props":{"bookingTrustItems":[{"icon":"check-circle","title":"Lizenzierter lokaler Anbieter","description":"In Busan lizenzierte Tourbegleitung","iconBg":"bg-emerald-50/80","iconColor":"text-emerald-600","body":"Lizenzierter lokaler Anbieter, der regelmäßig Stadttouren in Busan durchführt — mit zertifizierten englischsprachigen Guides, Fahrzeugversicherung und einer Routenplanung, die die vollsten Tempelstunden nach Möglichkeit meidet."},{"icon":"users","title":"Kleingruppe","description":"max. ≈12 Gäste","iconBg":"bg-pink-50/80","iconColor":"text-pink-600","body":"Der Kleingruppen-Minivan (max. ~12) hält Gamcheons enge Gassen und den 108-Stufen-Weg am Yonggungsa angenehm — ein großer Unterschied zu Bustouren mit 40 Personen."},{"icon":"shield","title":"Eintritte inklusive","description":"Wichtige Eintritte abgedeckt","iconBg":"bg-sky-50/80","iconColor":"text-sky-600","body":"Alle sieben Hauptstopps sind eintrittsfrei — auf der Kernroute fallen am Tag keine versteckten Kosten pro Sehenswürdigkeit an."}],"bookingSupportSteps":[{"timing":"Sofort","title":"Sofortige Bestätigung","detail":"Buchungsbestätigung mit Programmübersicht","description":"Sofortige Buchungsbestätigung mit Hinweisen zum Abholpunkt (Bahnhof Busan / Seomyeon / Haeundae)."},{"timing":"Am Vortag","title":"Abholdetails","detail":"Genauer Abholort und Fahrzeuginfo per WhatsApp","description":"Wettercheck und etwaige Routenhinweise (Danubi-Train-Tipp für Taejongdae, Gezeiten am Yonggungsa) werden am Vortag gesendet."},{"timing":"Am Morgen","title":"Abholbestätigung","detail":"Der Fahrer meldet sich 10 Minuten vor Ankunft","description":"Kennzeichen des Vans und Kontakt des Guides werden am Vorabend bestätigt."},{"timing":"Während der Tour","title":"Betreuung unterwegs","detail":"Direkter Draht zum Einsatzteam","description":"Eine Nachricht am Morgen bestätigt Ihre Abholstation und aktuelle Verkehrslage."},{"timing":"Am Tagesende","title":"Flexibler Ausstieg","detail":"Ausstieg wahlweise in Nampo-dong, am Bahnhof Busan, in Seomyeon oder Haeundae","description":"Der Guide erzählt an jedem Stopp vor Ort — Yonggungsas Gründung 1376, die 22-Nationen-Geschichte des UNMCK, Gamcheons Ursprung als Flüchtlingssiedlung von 1955."},{"timing":"Nach der Tour","title":"Bewertung & Nachbetreuung","detail":"Optionale Bewertung und Nachfassen","description":"Nach der Tour senden wir eine Feedback-Anfrage; Fragen zu Restaurantempfehlungen in Busan beantworten wir noch am selben Tag."}]}},{"id":"faq","section_html_id":"faq","component":"TourFaqSection","props":{"staticQuestions":[{"question":"Ist das Sky-Capsule-Ticket inbegriffen?","answer":"Ihre Wahl bei der Buchung. Buchen Sie die Option mit Ticket, reservieren wir die Kapseln für Ihre Gruppe im Voraus (Preis pro Kapsel: etwa ₩30,000 für 2 / ₩39,000 für 3 / ₩44,000 für 4, einfache Fahrt — die inbegriffene Option ist auf Basis von 2 Personen pro Kapsel kalkuliert). Buchen Sie die Basisoption, können Sie stattdessen den kostenlosen Green-Railway-Holzsteg (Uferpromenade) entlanggehen oder mit dem Bus nach Mipo fahren, während andere die Kapsel nehmen."},{"question":"Muss ich die Sky Capsule im Voraus reservieren?","answer":"Sonnenuntergangs- und Wochenendtermine sind 1–2 Wochen im Voraus ausverkauft. Wählen Sie die Option mit inbegriffenem Ticket, übernehmen wir die Reservierung für Ihre Gruppe, sobald die Buchung bestätigt ist. Tickets am Automaten am selben Tag sind an ruhigen Wochentagen möglich, aber nicht garantiert."},{"question":"Ist das Mittagessen inbegriffen?","answer":"Nein — das Mittagessen ist separat (etwa ₩10,000–15,000). Der Guide empfiehlt lokale Optionen nahe Haeundae/Mipo wie dwaeji-gukbap (Busans typische Schweinefleisch-Reissuppe), milmyeon (kalte Weizennudeln) oder ein Fischrestaurant."},{"question":"Wie viel wird gelaufen und wie steil ist es?","answer":"Moderat bis anspruchsvoll in kurzen Abschnitten: 108 Stufen hinab und wieder hinauf am Yonggungsa, ebener Glas-Skywalk am Daritdol, überwiegend eben an den Kapselstationen, Hanggassen in Gamcheon und Treppen in Dakbatgol — wo die kostenlose Monorail den Aufstieg für Sie übernimmt. Die Gesamtstrecke zu Fuß beträgt etwa 4–5 km."},{"question":"Ist die Tour für Kinder oder Senioren geeignet?","answer":"Ja, für die meisten aktiven Reisenden. Kinder lieben den Glasboden und die Kapsel; die Dakbatgol-Monorail erspart den steilsten Anstieg. Die Yonggungsa-Treppen und Gamcheons Steigungen sind die beiden fordernden Abschnitte — gehen Sie sie langsam an und lassen Sie Seitengassen bei Bedarf aus."},{"question":"Worin unterscheidet sich diese Tour von der Busan-Top-Attraktionen-Tagestour?","answer":"Gleicher Veranstalter, anderer Schwerpunkt. Die Top-Attraktionen-Tour deckt die klassische Stadtrunde ab (UN-Gedenkfriedhof, Jagalchi-Markt). Diese Kleingruppen-Route setzt voll auf Küste und Dörfer: ein eigener Stopp am Daritdol-Skywalk, die Fahrt mit der Sky Capsule mit Option auf inbegriffenes Ticket und das stille Dakbatgol-Wandmalereidorf, das die großen Busse auslassen."},{"question":"Wo holen Sie ab und wo setzen Sie ab?","answer":"Abholung an drei zentralen Stationen — Seomyeon (08:30), Bahnhof Busan (08:50), Haeundae (09:30). Die Ausstiege erfolgen der Reihe nach: Nampo-dong, Bahnhof Busan, Seomyeon, dann Haeundae, etwa 17:50–19:00."},{"question":"Was passiert bei Regen?","answer":"Die Tour findet bei jedem Wetter statt. Kapsel und Monorail fahren bei normalem Regen (sie pausieren nur bei starkem Wind), am Skywalk werden Schuhüberzieher gestellt, und die Dorfgassen bleiben mit Regenschirm begehbar. Bei schwerem Wetter kann sich die Außenzeit auf den Tempelterrassen verkürzen."}]}},{"id":"reviews","section_html_id":"reviews","component":"TourReviewsSection","props":{"guestReviews":[],"reviewsSummary":{"averageRating":0,"totalReviews":0,"ratingDistribution":[{"stars":5,"count":0,"percentage":0},{"stars":4,"count":0,"percentage":0},{"stars":3,"count":0,"percentage":0},{"stars":2,"count":0,"percentage":0},{"stars":1,"count":0,"percentage":0}],"highlights":[]}}},{"id":"sticky_booking","section_html_id":null,"component":"TourStickyBookingBar","props":{"note":"Wählen Sie Datum und Gruppengröße, um die Live-Verfügbarkeit zu prüfen und Ihre Buchung abzuschließen.","price":{"amountLabel":"59","currency":"USD","per":"person","salePriceUsd":59}}}]}'::jsonb
)
ON CONFLICT (slug, locale) DO NOTHING;

