inimal_walking_seekers","stroller_heavy_groups","nightlife_focused_travelers"],"anchor_pois":["Haedong Yonggungsa Temple","Cheongsapo Daritdol Observatory","Haeundae Blueline Park Sky Capsule","Gamcheon Culture Village","Dakbatgol Mural Village"],"anchor_poi_keys":["haedong_yonggungsa","cheongsapo_daritdol_observatory","cheongsapo_blue_line_park","gamcheon_culture_village","dakbatgol_mural_village"],"competing_products":["busan-top-attractions-day-tour","busan-small-group-sightseeing-tour-cruise-passengers","busan-private-car-charter-cruise-shore"],"reviews_attribution":"New product (2026-08) — no imported reviews; rating starts at 0.","unesco_fit_note":"No UNESCO property on this route. Cultural weight comes from the seaside temple (1376 founding), Korean-War refugee village heritage at Gamcheon, and hanji paper-mulberry heritage at Dakbatgol."},"itinerary_variants":[],"_publication":{"schema_version":"v4_canonical","created":"2026-08-04","last_modified":"2026-08-04","version_history":["v1_authored_2026_08_04"],"fix_passes":{"v1_authored_2026_08_04":"New product (owner instruction 2026-08-04). Donor: busan-top-attractions-day-tour — pickup/Yonggungsa/lunch-slot/Gamcheon stops, 3-station pickup_dropoff, Busan weather/glance/trust/support blocks reused per locale; Daritdol Observatory, Sky Capsule (ticket-optional), Dakbatgol Mural Village & wish-stairs monorail, and all product-level copy authored fresh in 6 locales (scripts/busan-smallgroup-content/). matching_profile derived from donor with identity/anchor patches — full KB calibration pending. Price set by owner (2026-08-04): USD 59 Sky Capsule ticket excluded / USD 79 ticket included. Daritdol and Dakbatgol ship without photos (no owned imagery yet)."}},"page_sections":[{"id":"hero","section_html_id":null,"component":"TourHeroSection","props":{"headlineLine1":"Морской храм, Sky Capsule","headlineLine2":"и культурные деревни","hero":{"imageUrl":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","imagePosition":"center 40%","images":["/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp"],"tagline":"Приморский храм Пусана в его тихий час, стеклянный скайвок над морем, поездка в пастельной капсуле вдоль побережья и две деревни на холмах — одна знаменитая, другая всё ещё по-настоящему местная","pills":["Мини-группа","Пусан","Подходит для первого визита"],"meta":{"duration":"≈ 10 часов (08:30 первая посадка, ≈ 18:30 последняя высадка в центре)","region":"Пусан","stops":"8 остановок","rating":0,"ratingStars":0}}}},{"id":"subnav","section_html_id":null,"component":"TourTabsNav","props":{"subnavItems":[{"id":"overview","label":"Обзор"},{"id":"itinerary","label":"Маршрут"},{"id":"practical","label":"Практично"},{"id":"reviews","label":"Отзывы"},{"id":"booking","label":"Бронирование"}]}},{"id":"overview","section_html_id":"overview","component":"TourAtAGlance","props":{"glanceItems":[{"icon":"camera","label":"Фотопотенциал","value":"Высокий","level":5},{"icon":"mountain","label":"Пейзажи","value":"Хорошие","level":4},{"icon":"footprints","label":"Ходьба","value":"Требовательная","level":4},{"icon":"cloud-rain","label":"Пригодность в дождь","value":"Средняя","level":3},{"icon":"users","label":"Подходит для семей","value":"Хорошо","level":4},{"icon":"gauge","label":"Темп","value":"Сбалансированный","level":4}]}},{"id":"atmosphere","section_html_id":null,"component":"TourAtmosphereGallery","props":{"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 1","alt":"Haedong Yonggungsa Temple — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-haesu-gwaneum.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 2","alt":"Haedong Yonggungsa Temple — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-dragon-hall.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 3","alt":"Haedong Yonggungsa Temple — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-main-courtyard.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 4","alt":"Haedong Yonggungsa Temple — gallery image 4"},{"id":5,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-zodiac-statues.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 5","alt":"Haedong Yonggungsa Temple — gallery image 5"},{"id":6,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 6","alt":"Haedong Yonggungsa Temple — gallery image 6"},{"id":7,"type":"photo","src":"/images/tours/cheongsapo-blue-line/cheongsapo-sky-capsule-interior.webp","location":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо)","caption":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо) — photo 1","alt":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо) — gallery image 1"},{"id":8,"type":"photo","src":"/images/tours/cheongsapo-blue-line/blueline-tram-cherry-sea.webp","location":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо)","caption":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо) — photo 2","alt":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо) — gallery image 2"},{"id":9,"type":"photo","src":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-01-01-18.webp","location":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо)","caption":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо) — photo 3","alt":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо) — gallery image 3"},{"id":10,"type":"photo","src":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-12-53-19.webp","location":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо)","caption":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо) — photo 4","alt":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо) — gallery image 4"},{"id":11,"type":"photo","src":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 1","alt":"Gamcheon Culture Village — gallery image 1"},{"id":12,"type":"photo","src":"/images/tours/gamcheon-culture-village/chatgpt-image-2026-5-11-01-00-53.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 2","alt":"Gamcheon Culture Village — gallery image 2"},{"id":13,"type":"photo","src":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 3","alt":"Gamcheon Culture Village — gallery image 3"},{"id":14,"type":"photo","src":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-day-sign.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 8","alt":"Gamcheon Culture Village — gallery image 8"}]}},{"id":"itinerary","section_html_id":"itinerary","component":"TourTimelineSection","props":{"itineraryStops":[{"name":"Посадка (3 центральные станции Пусана)","time":"≈ 08:30–09:30","number":1,"category":"Транспорт / Посадка","duration":"30 мин","timeUsed":["Посадка на вокзале Пусана (~09:00, ~5 мин)","Переезд до станции Сомён (~10 мин)","Посадка в Сомёне (~09:15, ~5 мин)","Переезд до станции Хэундэ (~15 мин)","Посадка в Хэундэ (~09:30, ~5 мин)"],"_poi_meta":{"match":"transit_only","poi_key":"OPS_busan_pickup_central","sources":["Visit Busan","Busan Metro"],"verified":true,"kb_version":"1.15","verified_date":"2026-04-29"},"highlights":["Три варианта посадки в центре Пусана (вокзал Пусана, Сомён, Хэундэ)","Микроавтобус для мини-группы (максимум ~14 чел.)","Общее время в пути до первой остановки: ~30-40 мин","Печатная корейско-английская карточка маршрута раздаётся при посадке"],"whyOnRoute":"Три точки посадки охватывают три главные гостиничные зоны Пусана (KTX/Нампхо, середина города Сомён, пляжный район Хэундэ), не заставляя гостей с утра пересекать весь город. Последовательность с северо-запада на восток минимизирует пробег микроавтобуса и приводит группу к Хэдон Ёнгунса около 10:00 — достаточно рано, чтобы опередить самый плотный поток туристических автобусов.","description":"Посадка объединена в трёх центральных транспортных узлах Пусана, чтобы день оставался удобным без метаний через весь город: **вокзал Пусана (линия 1)** — для гостей, живущих у терминала KTX или в районе Чхорян/Нампхо-дон; **станция Сомён (линии 1 и 2)** — самая загруженная пересадочная станция метро Пусана, удобная для гостей отелей середины города вокруг Lotte Hotel Busan и «Медицинской улицы» Сомёна; и **станция Хэундэ (линия 2)** — для гостей курортного района у пляжа рядом с Westin Josun, Park Hyatt и Signiel Busan. \n\nМикроавтобус забирает гостей на всех трёх точках по очереди (обычно сначала вокзал Пусана ~09:00, Сомён ~09:15, Хэундэ ~09:30), а затем направляется на северо-восток по прибрежному маршруту через мост Кванан в сторону уезда Кичжан (Gijang-gun) к первой остановке дня. \n\nОбщее время в пути от последней посадки до Хэдон Ёнгунса: ~30-40 минут в зависимости от трафика. Водитель раздаст печатную корейско-английскую карточку маршрута с таймингом; пожалуйста, будьте в точке посадки за 5 минут до назначенного времени, чтобы день не выбился из графика перед поздними остановками в деревнях Камчхон и Такпатколь.","_role":"pickup"},{"name":"Храм Хэдон Ёнгунса","time":"≈ 10:00","number":2,"category":"Буддийский храм / Побережье","duration":"75 мин","timeUsed":["Высадка из микроавтобуса + проход по торговой аллее к входной площади (~10 мин)","Двенадцать генералов зодиака + «пагода от аварий» (~10 мин)","Спуск по 108 ступеням + главный зал Тэунчжон + приморские террасы (~30 мин)","Смотровая у статуи Хэсу Кваным + время на фото (~15 мин)","Подъём обратно + сбор у микроавтобуса (~10 мин)"],"_poi_meta":{"match":"exact","poi_key":"haedong_yonggungsa","sources":["Visit Busan","VisitKorea","Wikipedia","Culture Trip","Korean Temple Guide","Korea Tourism Organization Official"],"verified":true,"kb_version":"1.24","verified_date":"2026-04-29"},"highlights":["**Основан в 1376 году** буддийским мастером Наон Хегыном (изначально «Помунса»)","Один из очень немногих крупных корейских храмов на берегу моря (большинство — в горах)","Переименован в **Хэдон Ёнгунса в 1974 году** после видения монаха Чонама — богиня на драконе","**108 каменных ступеней** = 108 заблуждений ума в буддизме","**12 Сибичжи-син (генералов зодиака)** у входа; **«пагода от аварий»** с монетами","**Хэсу Кваным Тэбуль** (морская богиня милосердия) — самый фотографируемый вид с утёса","Главный зал Тэунчжон восстановлен в 1970 году с вниманием к оригинальным цветам","Ежедневно 04:30-19:20, вход БЕСПЛАТНЫЙ; на день рождения Будды (май) — фестиваль фонарей","**Ряд каменных 12 Сибичжи-син — генералов зодиака — у ворот храма** — уникален среди прибрежных храмов Кореи"],"smartNotes":{"tip":"В залы входят через боковые двери (передняя предназначена для монахов); на день рождения Будды (апрель–май) храм украшают фонарями; приезжайте до 10:30, чтобы избежать самого плотного потока туристических автобусов","photo":"Скала восхода на морском краю; лестница у зала Тэунчжон даёт классический кадр «океан и храм»; статуя Хэсу Кваным с верхнего утёса — широкий план храма и Восточного моря","facilities":"Сувенирные и снековые лавки и небольшое кафе на верхней площади; прибрежная тропа ведёт дальше вдоль скал"},"whyOnRoute":"**Знаковое начало маршрута — самый фотографируемый храм Пусана в его тихое окно.** Прибытие к 10:00 опережает основной наплыв туристических автобусов (обычно с 11:00), поэтому спуск по 108 ступеням и смотровая точка со статуей Хэсу Кваным ещё проходимы без очередей. К тому же расположение храма на скалах уезда Кичжан (Gijang-gun) начинает день в самой северо-восточной точке маршрута — всё дальнейшее течёт в одну сторону вдоль побережья: следом Чхонсапхо, затем капсула в сторону города — без возвратов.","convenience":{"parking":"Парковка Хэдон Ёнгунса (платная, по данным Visit Busan)","restroom":"Есть у главного входа и на территории комплекса"},"description":"**Хэдон Ёнгунса (해동 용궁사) — самый знаменитый приморский буддийский храм Кореи** — стоит на скалистых утёсах уезда Кичжан (Gijang-gun) на северо-восточном побережье Пусана, один из очень немногих крупных корейских храмов, НЕ расположенных в горах. Основан в **1376 году, в эпоху династии Корё, великим буддийским наставником Наон Хегыном (나옹 혜근, 1320-1376)** — королевским советником и мастером, который во многом сформировал корейский буддизм на пороге эпохи Чосон. \n\nПо легенде, Наон предавался аскезе в храме Пунхванса в Кёнджу во время общенациональной засухи; бог Восточного моря явился ему во сне и сказал, что храм на горе Поннэ (изначальное название этого приморского утёса) вернёт королевству процветание. \n\nНаон основал храм и назвал его **Помунса**, посвятив его Квансеым-посаль (관세음보살, бодхисаттве сострадания). Храм был разрушен во время **японского вторжения Имчжин 1592 года** и лежал в руинах более 300 лет, пока **монах Унган из храма Тхондоса не начал восстановление в начале 1930-х годов**. \n\nНынешнее название, **Хэдон Ёнгунса («храм Драконьего дворца»)**, появилось только в **1974 году** — когда настоятелю Чонаму во время 100-дневной молитвы (чонгон кидо) явилось видение богини милосердия, спускающейся на спине дракона в сиянии многоцветного света. \n\nХрам переименовали в честь этого видения. Визит следует фирменному процессионному пути храма: через ряд **12 Сибичжи-син (двенадцати генералов зодиака)** на входной площади, мимо **7-ярусной «пагоды от аварий»** (где водители оставляют монеты под каменным святилищем-колесом), вниз по знаменитым **108 каменным ступеням** (символизирующим 108 заблуждений буддийского ума) через небольшую бамбуковую рощу — и на приморские террасы к главному залу Тэунчжон. \n\n**Хэсу Кваным Тэбуль** (статуя морской богини милосердия) на верхнем утёсе — самый фотографируемый вид, в одном кадре крыши храма и Восточное море. \n\nЧасы работы: **04:30-19:20 ежедневно, последний вход 18:50, вход БЕСПЛАТНЫЙ**. На **день рождения Будды (май)** храм украшают фонари фестиваля Ёндынхве.","visitBasics":{"hours":"Ежедневно 04:30–19:20 (последний вход 18:50)","closed":"Открыт круглый год","walking":"Умеренная нагрузка — 108 ступеней через сосновую рощу, несколько приморских террас и лестниц","admission":"Бесплатно; парковка для личных автомобилей платная"},"image":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","images":["/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-haesu-gwaneum.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-dragon-hall.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-main-courtyard.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-zodiac-statues.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp"],"imageCredits":[{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-haesu-gwaneum.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-dragon-hall.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-main-courtyard.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-zodiac-statues.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 1","alt":"Haedong Yonggungsa Temple — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-haesu-gwaneum.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 2","alt":"Haedong Yonggungsa Temple — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-dragon-hall.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 3","alt":"Haedong Yonggungsa Temple — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-main-courtyard.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 4","alt":"Haedong Yonggungsa Temple — gallery image 4"},{"id":5,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-zodiac-statues.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 5","alt":"Haedong Yonggungsa Temple — gallery image 5"},{"id":6,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 6","alt":"Haedong Yonggungsa Temple — gallery image 6"}]},{"number":3,"time":"≈ 11:45","duration":"40 мин","name":"Смотровая площадка Таритдоль в Чхонсапхо (стеклянный скайвок)","category":"Прибрежная смотровая / бесплатно","description":"**Смотровая площадка Таритдоль в Чхонсапхо (청사포 다릿돌전망대)** — это **скайвок длиной 72,5 метра, изгибающийся над морем на высоте около 20 метров**, открытый в августе 2017 года на прибрежном утёсе между Чхонсапхо и Сончжоном. Название происходит от **таритдоль — пяти рифовых «камней-ступеней»**, что усеивают море под настилом и будто шагают к горизонту, как мост. Дальняя секция настила — со **стеклянным** полом; выдаются бахилы, чтобы беречь панели (и довериться им!), пока внизу под ногами перекатывается зыбь. Вход **бесплатный**. Вернувшись в деревню, в нескольких минутах прогулки вы найдёте **парные маяки Чхонсапхо** (один красный, один белый) и маленький переезд у станции, прославившийся кадром в стиле аниме «Слэм-данк».","image":null,"highlights":["**Скайвок 72,5 м, ~20 м над морем** — открыт в августе 2017 года, БЕСПЛАТНО","Назван в честь пяти рифов **таритдоль — «камней-ступеней»**, видимых под настилом","**Секция со стеклянным полом** на морском конце (бахилы выдаются)","**Парные маяки Чхонсапхо** (красный + белый) в нескольких минутах прогулки","Чхонсапхо — один из **восьми живописных видов** Пусана, действующая рыбацкая деревня","Знаменитый по аниме переезд у станции — фотоспот"],"timeUsed":["Высадка из микроавтобуса + пешком до входа на скайвок (~5 мин)","Выход на скайвок + секция со стеклянным полом (~20 мин)","Прогулка к парным маякам / переезду для фото (~10 мин)","Сбор у станции капсулы (~5 мин)"],"whyOnRoute":"**Бесплатный аттракцион между храмом и капсулой.** Таритдоль дарит дню его момент «над морем» — стеклянный пол, под которым перекатывается зыбь, — без билета, и стоит он прямо на утёсе Чхонсапхо, так что посадка на Sky Capsule всего в паре минут. Увидев берег сначала с неподвижного скайвока, вы через десять минут воспримете вид из движущейся капсулы совсем иначе.","_poi_meta":{"match":"authored","poi_key":"cheongsapo_daritdol_observatory","sources":["Visit Busan","Busan Metropolitan City Tourism","Blue Line Park official"],"verified":false,"verified_date":"2026-08-04"},"smartNotes":{"tip":"В ветреные дни настил иногда закрывают — гид проверяет условия и при необходимости меняет порядок остановок кластера Чхонсапхо","photo":"Снимайте вниз сквозь стекло на рифы таритдоль; изгиб настила с береговой тропы даёт лучший общий кадр","facilities":"Кафе и лавки с морепродуктами в деревне Чхонсапхо внизу"},"convenience":{"parking":"Остановка микроавтобуса в деревне Чхонсапхо; короткая прогулка до настила","restroom":"Общественные туалеты у станции Чхонсапхо"},"visitBasics":{"hours":"Открытый доступ; смотровая обслуживается примерно 09:00–18:00 (зависит от сезона/погоды)","closed":"Может временно закрываться при сильном ветре или шторме","walking":"Ровный выход по настилу; короткий подъём от деревни","admission":"БЕСПЛАТНО (бахилы выдаются для стеклянной секции)"},"images":[],"imageCredits":[],"galleryItems":[]},{"number":4,"time":"≈ 12:35","duration":"40 мин","name":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо)","category":"Прибрежный аттракцион / билет по выбору","description":"**Sky Capsule («Скай-капсула»)** — фирменный аттракцион **Haeundae Blueline Park (парка «Блюлайн» в Хэундэ)**, эко-редевелопмента 2020 года заброшенной прибрежной железной дороги Тонхэ-Намбу: **пастельные 4-местные кабинки скользят 2,3 км по эстакадному рельсу на высоте 7–10 метров над береговой линией** между Чхонсапхо и Мипхо, и всю дорогу море с одной стороны (~30 минут). Мы садимся в **Чхонсапхо и едем в сторону Мипхо**, где микроавтобус уже ждёт — так поездка одновременно служит трансфером дня вдоль побережья. **Билет на капсулу опционален и выбирается при бронировании**: при варианте с включённым билетом мы заранее резервируем капсулы для вашей группы (цена за капсулу: около ₩30,000 за 2 чел. / ₩39,000 за 3 / ₩44,000 за 4, в одну сторону); при базовом варианте вы можете пройтись по **бесплатной деревянной набережной Green Railway** — отмеченной наградами 2,3-километровой прибрежной дощатой тропе под тем же рельсом — или просто доехать до Мипхо на микроавтобусе.","image":"/images/tours/cheongsapo-blue-line/cheongsapo-sky-capsule-interior.webp","highlights":["**Пастельные 4-местные капсулы на эстакадном прибрежном рельсе** — фирменный аттракцион парка «Блюлайн» (открыт в 2020 году)","**Чхонсапхо → Мипхо, 2,3 км / ~30 мин**, виды на море всю дорогу","**Билет включён или не включён — ваш выбор при бронировании** (цена за капсулу ≈ ₩30,000 за 2 чел. / ₩39,000 за 3 / ₩44,000 за 4, в одну сторону)","Кто не едет: **бесплатная деревянная набережная Green Railway** вдоль того же берега или микроавтобус до Мипхо","Поездка заканчивается там, где начинается обед — от Мипхо рукой подать до гастрономических улиц Хэундэ","Работает при обычном дожде; останавливается только при сильном ветре"],"timeUsed":["Посадка на станции Чхонсапхо (~10 мин)","Поездка на Sky Capsule Чхонсапхо → Мипхо (~30 мин)"],"whyOnRoute":"**Аттракцион, который одновременно трансфер.** Посадка в Чхонсапхо сразу после скайвока означает, что капсула везёт вас вдоль того самого берега, на который вы только что смотрели, — и высаживает в Мипхо, где уже ждут микроавтобус и обеденные улицы. День ради неё никуда не сворачивает: откажитесь от билета — и тот же отрезок покроют микроавтобус или бесплатная набережная.","_poi_meta":{"match":"partial","poi_key":"cheongsapo_blue_line_park","sources":["Blue Line Park official","Visit Busan","Busan Metropolitan City Tourism"],"verified":true,"kb_version":"1.24","verified_date":"2026-08-04"},"smartNotes":{"tip":"Слоты на закат и выходные распродаются за 1–2 недели — выберите вариант с включённым билетом при бронировании, и мы зарезервируем их для вас","photo":"Садитесь со стороны моря (правая сторона по ходу к Мипхо); поворот за тоннелем Тальмачжи — фирменный кадр","facilities":"Кафе и мини-маркет на площади Мипхо; билетные киоски на обеих станциях"},"convenience":{"parking":"Микроавтобус встречает группу на площади у станции Мипхо","restroom":"На обеих станциях — Чхонсапхо и Мипхо"},"visitBasics":{"hours":"≈ 09:30–18:30 (в высокий сезон — до вечера)","closed":"Зависит от погоды; при сильном ветре движение останавливают","walking":"Ровные платформы станций; альтернатива-набережная — 2,3 км (~30 мин) по деревянному настилу","admission":"За капсулу, в одну сторону: ≈ ₩30,000 (2 чел.) / ₩39,000 (3) / ₩44,000 (4) — вариант с включённым билетом доступен при бронировании"},"images":["/images/tours/cheongsapo-blue-line/cheongsapo-sky-capsule-interior.webp","/images/tours/cheongsapo-blue-line/blueline-tram-cherry-sea.webp","/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-01-01-18.webp","/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-12-53-19.webp"],"imageCredits":[{"url":"/images/tours/cheongsapo-blue-line/cheongsapo-sky-capsule-interior.webp","source":"atoc-korea"},{"url":"/images/tours/cheongsapo-blue-line/blueline-tram-cherry-sea.webp","source":"atoc-korea"},{"url":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-01-01-18.webp","source":"atoc-korea"},{"url":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-12-53-19.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/cheongsapo-blue-line/cheongsapo-sky-capsule-interior.webp","location":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо)","caption":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо) — photo 1","alt":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо) — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/cheongsapo-blue-line/blueline-tram-cherry-sea.webp","location":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо)","caption":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо) — photo 2","alt":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо) — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-01-01-18.webp","location":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо)","caption":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо) — photo 3","alt":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо) — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-12-53-19.webp","location":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо)","caption":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо) — photo 4","alt":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо) — gallery image 4"}]},{"name":"Обед (местный ресторан у Хэундэ/Мипхо)","time":"≈ 13:25","number":5,"category":"Местная кухня","duration":"60 мин","timeUsed":["Пешком от станции Мипхо до ресторана (~5 мин)","Обед (~50 мин)","Сбор у микроавтобуса (~5 мин)"],"_poi_meta":{"match":"lunch_placeholder","poi_key":"OPS_busan_lunch","sources":["Visit Busan","Busan Metropolitan Government cuisine guide"],"verified":true,"kb_version":"1.15","verified_date":"2026-04-29"},"highlights":[],"whyOnRoute":"**Естественная пауза между побережьем и деревнями.** Поездка в капсуле заканчивается в Мипхо как раз к обеду, а гастрономические улицы Хэундэ — в нескольких минутах ходьбы от станции: не нужно никуда ехать, чтобы хорошо поесть. Подкрепившись здесь, вы будете готовы к двум деревням на холмах, где ходьба самая «вертикальная» за день.","description":"Примерно 60 минут на обед у Мипхо/Хэундэ сразу после прибытия Sky Capsule. Типичные рекомендации гида: **твэджи-кукпаб (돼지국밥)** — фирменный пусанский суп на свином бульоне с рисом, родившийся в эпоху беженцев Корейской войны (~₩10,000), холодная пшеничная лапша **мильмён** или столик с морепродуктами у гавани. Обед не включён (≈ ₩10,000–15,000), так что вы сами выбираете то, что подходит вашему аппетиту и бюджету."},{"name":"Культурная деревня Камчхон","time":"≈ 15:00","number":6,"category":"Культурная деревня / Фрески","duration":"90 min","timeUsed":["Высадка на общественной парковке №2 + пешком до входа (~5 мин)","Туристический информационный центр + покупка карты-штампа (~10 мин)","Смотровая «Небесный сад» + скамейка Маленького принца (~25 мин)","Прогулка по переулкам мимо фресок + пауза в маленьком кафе (~25 мин)","Сбор у микроавтобуса (~10 мин)"],"_poi_meta":{"match":"exact","poi_key":"gamcheon_culture_village","sources":["Wikipedia","CNN","Visit Busan","Hapskorea","Columban Society","Lifeguin","Busan Cultural Foundation"],"verified":true,"kb_version":"1.24","verified_date":"2026-04-29"},"highlights":["**«Корейский Мачу-Пикчу» / «корейский Санторини»** — премия UN-HABITAT Asian Townscape Award 2012","Истоки: переселение администрацией Пусана в **1920-1930-е** + **беженцы Тхэгыкто 1955 года** (~800 семей)","**Философия Тхэгыкто «дай процветать другим»** = ни один дом не закрывает вид дому позади","**2009 «Мечтая о Мачу-Пикчу» + 2010 «Миро миро»** — паблик-арт-проекты министерства культуры","**Скамейка «Маленький принц и Лис»** в «Небесном саду» — самое фотографируемое место деревни","**~1,4 миллиона гостей в год** после паблик-арт-возрождения","**Живой жилой квартал** — тихие голоса, без дронов, без вспышки в сторону домов","Вход в деревню бесплатный; карта-штамп по желанию ~₩2,000","**Премия UN-HABITAT Asian Townscape Award 2012** — признание арт-проекта 2009 года «Мечтая о Мачу-Пикчу», превратившего поселение беженцев Тхэгыкто 1955 года в фирменную деревню фресок Пусана"],"smartNotes":{"tip":"Здесь живут люди — говорите тихо, без дронов, уносите мусор с собой; наденьте обувь с цепким протектором для крутых переулков; послеобеденный «золотой час» ~16:00-17:00 — лучший свет в деревне","photo":"Скамейка «Маленький принц и Лис» (длинная очередь) и смотровая «Ханыль Мару» / «Небесный сад» — ради панорамы радужных крыш и залива","facilities":"Прокат ханбока, ремесленные мастерские, лавки корейских сладостей, кафе; небольшой музей деревни у входа; карта-штамп — самый простой способ ориентироваться"},"whyOnRoute":"**Главная деревня второй половины дня — пастельный амфитеатр Пусана.** После прибрежного утра день переходит на западные холмы, где террасы Камчхона, построенные беженцами Корейской войны и возрождённые как арт-деревня в 2009 году, поднимаются леденцовыми красками над морем. 90-минутный маршрут охватывает смотровые точки, уступ с Маленьким принцем и время на прогулку по переулкам — и он намеренно поставлен в пару с тихим Такпатколем сразу после, чтобы вы увидели и знаменитую деревню, и местную, которую автобусы пропускают.","convenience":{"parking":"Общественная парковка Камчхон №2 (платная)","restroom":"Общественные туалеты у туристического информационного центра и у главных смотровых точек"},"description":"**Культурная деревня Камчхон (감천문화마을)** — прозванная и **«корейским Мачу-Пикчу»**, и **«корейским Санторини»** — это квартал на склоне холма в округе Саха-гу на западе Пусана, где дома в пастельных тонах спускаются по склону ступенчатыми рядами. \n\nПоселение возникло в **1920-1930-е годы**, когда администрация Пусана переселяла рабочих подальше от порта. Характер деревни сложился в **1955 году**, когда **~800 семей (около 4 000 человек) религиозной общины Тхэгыкто** — уникальной корейской синкретической религии, соединившей буддийские, конфуцианские и инь-янские элементы и основанной **Чо Чхольчже** в период японской колонизации, — поселились здесь как беженцы Корейской войны с Севера. \n\nФилософия Тхэгыкто «**дай процветать другим**» напрямую сформировала самую характерную черту деревни: дома намеренно поставлены ярусами так, что **ни одна крыша не закрывает вид дому позади**, и вся община открыта небу и морю. Камчхон оставался одним из беднейших кварталов Пусана до **2009 года**, когда министерство культуры Кореи запустило проект паблик-арт-возрождения **«Мечтая о Мачу-Пикчу в Пусане»**, а следом — проект **«Миро миро» («лабиринт») в 2010 году**, добавивший более 22 заказных фресок, скульптур и арт-инсталляций, включая знаменитую **скамейку «Маленький принц и Лис»** на смотровой точке «Небесный сад». \n\nКамчхон получил **премию UN-HABITAT Asian Townscape Award 2012** и теперь принимает **~1,4 миллиона гостей в год**. Визит следует фирменному маршруту с карта-штампами: от входа у **туристического информационного центра** — вверх к смотровой точке **«Небесный сад»** ради панорамного кадра радужных крыш, затем вниз сквозь лабиринт переулков мимо фресок, прокатов ханбока, ремесленных мастерских и маленьких кафе. \n\n**Деревня — живой жилой квартал**: говорите тихо, никаких дронов, не снимайте со вспышкой в сторону домов и уносите мусор с собой. \n\nЧасы работы: **09:00-18:00 март–октябрь / 09:00-17:00 ноябрь–февраль (инфоцентр)**; **сама деревня открыта круглосуточно, вход БЕСПЛАТНЫЙ**.","visitBasics":{"hours":"Ежедневно 09:00–18:00 (март–октябрь) / 09:00–17:00 (ноябрь–февраль); у части магазинов и кафе свои часы","closed":"Открыта круглый год (живой жилой квартал)","walking":"Высокая нагрузка — очень крутые переулки и лестницы; на многих участках не подходит для колясок и инвалидных кресел","admission":"Вход в деревню бесплатный; карта-штамп по желанию ≈ 2,000 KRW"},"image":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","images":["/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","/images/tours/gamcheon-culture-village/chatgpt-image-2026-5-11-01-00-53.webp","/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","/images/tours/gamcheon-culture-village/gamcheon-little-prince-day-sign.webp"],"imageCredits":[{"url":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/chatgpt-image-2026-5-11-01-00-53.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-day-sign.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 1","alt":"Gamcheon Culture Village — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/gamcheon-culture-village/chatgpt-image-2026-5-11-01-00-53.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 2","alt":"Gamcheon Culture Village — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 3","alt":"Gamcheon Culture Village — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-day-sign.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 8","alt":"Gamcheon Culture Village — gallery image 8"}]},{"number":7,"time":"≈ 16:50","duration":"50 мин","name":"Деревня фресок Такпатколь и монорельс у «лестницы желаний»","category":"Деревня фресок / бесплатный монорельс","description":"**Такпатколь (닥밭골)** — деревня на склоне холма в округе Со-гу в Пусане, чьё название хранит память о **полях бумажной шелковицы (так)**, когда-то снабжавших корейских мастеров традиционной бумаги ханчжи. Как и Камчхон, она карабкается по крутому склону тесными переулками — но так и не стала остановкой туристических автобусов, поэтому её **переулки с фресками, работы с мотивами ханчжи и смотровые точки остаются тихими и местными** — с бельевыми верёвками и всем прочим. Достопримечательность деревни — **«лестница желаний» (소망계단)** — длинная крутая лестничная улица, расписанная фресками, — и **бесплатный наклонный монорельс**, скользящий рядом с ней: его установили, чтобы пожилые жители деревни могли добираться до своих домов; на нём катаются и гости, превращая самый крутой подъём второй половины дня в смотровую площадку в замедленном движении. Это намеренно человечный по масштабу контрапункт славе Камчхона — в десяти минутах от зоны высадок.","image":null,"highlights":["**Тихая деревня фресок** — местный двойник Камчхона почти без туристов","Названа в честь **полей бумажной шелковицы (так)** — наследия пусанской бумаги ханчжи","**«Лестница желаний» (소망계단)** — крутая лестничная улица с фресками","**Бесплатный наклонный монорельс** вдоль лестницы — построен для пожилых жителей, открыт для гостей","Смотровые точки на склоне с видом на старый портовый квартал","Вход БЕСПЛАТНЫЙ; по-настоящему жилой квартал — говорите тихо"],"timeUsed":["Высадка из микроавтобуса + прогулка по переулкам с фресками (~20 мин)","Подъём на монорельсе у «лестницы желаний» + смотровая (~15 мин)","Спуск + время на фото (~10 мин)","Сбор у микроавтобуса (~5 мин)"],"whyOnRoute":"**Тихий финал, который автобусы пропускают.** После толп Камчхона Такпатколь показывает тот же холмистый Пусан на «живой громкости» — фрески, лестница желаний и монорельс, который поднимается за вас. Он закрывает главу деревень в десяти минутах от зоны высадки Нампхо, так что день заканчивается в глубине местной жизни, а не в пробке.","_poi_meta":{"match":"authored","poi_key":"dakbatgol_mural_village","sources":["Visit Busan","Busan Seo-gu Office"],"verified":false,"verified_date":"2026-08-04"},"smartNotes":{"tip":"Это жилая деревня, а не тематический парк — говорите тихо в переулках и не фотографируйте в открытые двери домов","photo":"Снимайте «лестницу желаний» снизу, с рельсом монорельса сбоку; верхняя смотровая обрамляет портовый квартал","facilities":"Небольшие кафе у входа; больше вариантов в Нампхо-доне после высадки"},"convenience":{"parking":"Остановка микроавтобуса у входа в деревню","restroom":"Общественный туалет у входа в деревню"},"visitBasics":{"hours":"Открытая деревня; монорельс работает в дневные часы (≈ 09:00–18:00, зависит от погоды)","closed":"Монорельс может останавливаться на обслуживание или в шторм — лестница остаётся открытой","walking":"Крутые переулки и лестницы; самый крутой участок покрывает монорельс","admission":"БЕСПЛАТНО (деревня и монорельс)"},"images":[],"imageCredits":[],"galleryItems":[]},{"number":8,"time":"≈ 17:50","duration":"≈ 70 мин всего","name":"Высадка (4 точки в центре Пусана)","category":"Высадка — последовательно по центральным станциям","description":"**Высадки идут последовательно с запада обратно на восток**: **район Нампхо-дон / рынок Чагальчхи (~17:50)** — выходите здесь ради лучших вечерних гастрономических улиц Пусана и ночной жизни площади BIFF; **вокзал Пусана (~18:10)** — для пересадки на KTX; **Сомён (~18:30)** — для центрального кластера отелей; и **Хэундэ (~19:00)** — последняя. Выберите точку высадки с гидом в течение дня: ехать до Хэундэ дольше всего, зато вечер вы встретите у пляжа.","image":null,"highlights":[],"timeUsed":["Район Нампхо-дон / Чагальчхи (~17:50)","Вокзал Пусана (~18:10)","Сомён (~18:30)","Хэундэ (~19:00)"],"whyOnRoute":"Такпатколь находится в десяти минутах от Нампхо-дона, поэтому последовательность высадок начинается почти сразу после последней остановки — без «мёртвого» времени в пути. Порядок с запада на восток зеркалит утренние посадки и охватывает пассажиров KTX (вокзал Пусана), центральные отели (Сомён) и пляжные отели (Хэундэ) без возвратов.","_poi_meta":null,"images":[],"imageCredits":[],"galleryItems":[]}]}},{"id":"day_flow","section_html_id":null,"component":"TourDayFlowSection","props":{"routeFlowStops":[{"name":"Посадка (3 центральные станции Пусана)","type":"origin","theme":"Departure"},{"name":"Храм Хэдон Ёнгунса","type":"primary","theme":"Seaside temple"},{"name":"Смотровая площадка Таритдоль в Чхонсапхо (стеклянный скайвок)","type":"secondary","theme":"Glass Skywalk"},{"name":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо)","type":"primary","theme":"Sky Capsule"},{"name":"Обед (местный ресторан Пусана)","type":"meal","theme":"Meal"},{"name":"Культурная деревня Камчхон","type":"primary","theme":"Art village"},{"name":"Деревня фресок Такпатколь и монорельс у «лестницы желаний»","type":"secondary","theme":"Mural Village"},{"name":"Высадка (4 точки в центре Пусана)","type":"return","theme":"Return"}],"routePhases":[{"phase":"Прибрежное утро","duration":"≈ 3 часа","description":"Посадка на трёх центральных станциях (08:30–09:30), затем храм Хэдон Ёнгунса до наплыва туристических автобусов и далее — стеклянный скайвок Таритдоль в Чхонсапхо."},{"phase":"Sky Capsule + обед","duration":"≈ 2 часа","description":"Поездка в пастельной Sky Capsule от Чхонсапхо до Мипхо (билет по выбору — те, кто не едет, отправляются на микроавтобусе или идут пешком по деревянной набережной-променаду Green Railway), затем обед у Хэундэ."},{"phase":"Две деревни на холмах","duration":"≈ 3 часа","description":"Фотомаршрут по культурной деревне Камчхон (90 мин), затем тихая деревня фресок Такпатколь и её бесплатный монорельс у «лестницы желаний» (50 мин)."},{"phase":"Финал в центре","duration":"≈ 1 час","description":"Последовательные высадки: Нампхо-дон, вокзал Пусана, Сомён, затем Хэундэ."}],"routeShapeIntro":{"title":"Как устроен этот день в Пусане","subtitle":"Сначала восточное побережье: приморский храм в его тихое утреннее окно, затем кластер Чхонсапхо — стеклянный скайвок, парные маяки, — где сама поездка на Sky Capsule становится трансфером вдоль берега до Мипхо. После обеда день переходит на западные холмы Пусана — две деревни в двух настроениях: всемирно известные краски Камчхона, а затем тихие фрески Такпатколя, где бесплатный монорельс скользит вверх вдоль «лестницы желаний». Высадки в центре замыкают маршрут: с 08:30 примерно до 18:30."}}},{"id":"details","section_html_id":"details","component":"TourFitSection","props":{"whyTourWorks":{"bestFor":["Тем, кто в Пусане впервые","Парам и любителям фотографии","Взрослым семьям и компаниям друзей","Тем, кто хочет увидеть и побережье, И деревни за один день"],"lessIdealFor":["Тем, кто хочет минимум ходьбы и без подъёмов","Группам с колясками (узкие переулки и лестницы в деревнях)","Любителям ночных панорам — это дневной маршрут"],"routeLogicSections":[{"title":"Pacing & geography","icon":"route","iconBg":"bg-sky-50/80","iconColor":"text-sky-600","items":[{"label":"Храм в его тихое окно","detail":"Хэдон Ёнгунса — самый фотографируемый храм Пусана, и наплыв туристических автобусов начинается около 11:00. Прибытие примерно к 10:00 позволяет спуститься по 108 ступеням и дойти до смотровой точки со статуей Хэсу Кваным без очередей."},{"label":"Поездка в капсуле И ЕСТЬ трансфер","detail":"От Чхонсапхо пастельная Sky Capsule скользит 2,3 км вдоль побережья до Мипхо — так поездка заменяет переезд на микроавтобусе, а не добавляет крюк. Гости без билета едут до Мипхо на микроавтобусе или идут пешком по бесплатной деревянной набережной-променаду Green Railway вдоль того же берега."},{"label":"Две деревни на холмах, два настроения","detail":"Камчхон — всемирно известный пастельный амфитеатр Пусана; Такпатколь в десяти минутах — его тихий местный двойник: переулки с фресками почти без туристов, где бесплатный наклонный монорельс, построенный для пожилых жителей деревни, поднимает вас вдоль «лестницы желаний»."},{"label":"Бесплатные ключевые точки, один опциональный билет","detail":"Ёнгунса, скайвок Таритдоль, Камчхон и Такпатколь (включая монорельс) — всё бесплатно. Единственная платная достопримечательность дня — Sky Capsule, и это ваш выбор при бронировании: билет включён — или не включён, если вы предпочитаете прогулку по набережной."}]}]}}},{"id":"practical","section_html_id":null,"component":"TourPracticalDetails","props":{"practicalAccordionItems":[{"id":"pickup","title":"Посадка и высадка","preview":"Три точки посадки вдоль метро Пусана: станция Сомён, выход 4 (08:30), вокзал Пусана, выход 4 — не турникеты KTX (08:50), станция Хэундэ, выход 5 (09:30).","content":["Три точки посадки вдоль метро Пусана: станция Сомён, выход 4 (08:30), вокзал Пусана, выход 4 — не турникеты KTX (08:50), станция Хэундэ, выход 5 (09:30).","Высадка по порядку: Нампхо-дон/Чагальчхи ≈17:50, вокзал Пусана ≈18:10, Сомён ≈18:30, Хэундэ ≈19:00.","Фактическая длительность тура зависит от точки посадки: Сомён ≈10 ч, Хэундэ ≈9,5 ч."]},{"id":"what-to-bring","title":"Что надеть и взять с собой","preview":"Удобная обувь с цепкой подошвой — переулки Камчхона на склоне и 108 ступеней Ёнгунса…","content":["Удобная обувь с цепкой подошвой — и переулки Камчхона на склоне, и 108 ступеней Ёнгунса требуют сцепления.","Лёгкий слой одежды — для кондиционера в транспорте и морского бриза у Ёнгунса.","Фотоаппарат или смартфон (Камчхон и Чхонсапхо — главные фототочки).","Наличные или карта — на обед (₩10,000–₩20,000), опциональные билеты на Sky Capsule / пляжный поезд в Чхонсапхо и опциональную смотровую башни Пусана."]},{"id":"weather-policy","title":"Погодная политика","preview":"Работаем круглый год.","content":["Работаем круглый год.","Лёгкий дождь: тур идёт по расписанию — у Ёнгунса под дождём своя атмосфера, а переулки Камчхона остаются проходимыми.","Сильный дождь или шторм: гид может скорректировать маршрут, потому что нижняя часть храма Ёнгунса становится скользкой, а лестницы Камчхона — небезопасными.","Погода уровня тайфуна: предлагается полный возврат или перенос бронирования."]},{"id":"inclusions","title":"What''s included","preview":"Микроавтобус для мини-группы (максимум ≈12 гостей), лицензированный англоговорящий гид, топливо/платные дороги/парковка.","content":["Микроавтобус для мини-группы (максимум ≈12 гостей), лицензированный англоговорящий гид, топливо/платные дороги/парковка.","Все ключевые достопримечательности — с БЕСПЛАТНЫМ входом: Хэдон Ёнгунса, смотровая площадка Таритдоль в Чхонсапхо, культурная деревня Камчхон, деревня фресок Такпатколь (монорельс у «лестницы желаний» бесплатный).","Билет на Sky Capsule: выбор при бронировании — включён (мы заранее резервируем капсулы для вашей группы; из расчёта 2 человека на капсулу) или не включён (прогулка по бесплатной деревянной набережной Green Railway или переезд до Мипхо на микроавтобусе).","Не включено: обед (≈ ₩10,000–15,000), напитки, личные расходы, чаевые."]},{"id":"language","title":"Язык","preview":"Основной язык тура: английский.","content":["Основной язык тура: английский.","Гид с китайским языком — по запросу; бронируйте за 3+ дня.","Корейский звучит весь день — в меню, на вывесках и у лавок; гид берёт перевод на себя."]},{"id":"walking","title":"Walking & terrain","preview":"Умеренная сложность с короткими требовательными отрезками.","content":["Умеренная сложность с короткими требовательными отрезками.","В Ёнгунса — 108 каменных ступеней вниз и обратно вверх.","Скайвок Таритдоль — ровный (стеклянный пол, бахилы выдаются).","Станции Sky Capsule — ровные, лишь несколько ступеней на платформах.","Камчхон — переулки и лестницы на склоне; наденьте удобную обувь.","«Лестница желаний» в Такпатколе крутая, но подъём берёт на себя бесплатный монорельс.","Всего пешком — около 4–5 км."]},{"id":"capsule","title":"Sky Capsule (билет по выбору)","preview":"Включён или не включён — ваш выбор при бронировании.","content":["Sky Capsule проходит 2,3 км по эстакадному рельсу между Чхонсапхо и Мипхо (~30 мин) — пастельные 4-местные кабинки над береговой линией.","Вариант с включённым билетом: мы заранее резервируем капсулы для вашей группы (цена за капсулу ≈ ₩30,000 за 2 чел. / ₩39,000 за 3 / ₩44,000 за 4, в одну сторону; вариант с включённым билетом рассчитан из расчёта 2 человека на капсулу).","Вариант без билета: прогулка по бесплатной деревянной набережной Green Railway (2,3 км, ~30 мин, вдоль того же берега) или переезд до Мипхо на микроавтобусе.","Работа зависит от погоды (при сильном ветре линию останавливают); если капсула не работает, прогулка по набережной и трансфер на микроавтобусе сохраняют график маршрута."]},{"id":"cancellation","title":"Отмена","preview":"Бесплатная отмена до 24 часов до посадки.","content":["Бесплатная отмена до 24 часов до посадки.","Отмена в день тура и неявка не возмещаются."]}],"practicalWeatherStatic":{"today":{"temp":"—","label":"См. сезонные заметки"},"tomorrow":{"temp":"—","label":"См. сезонные заметки"},"_seasonalSummary":"Пусан — самый южный крупный город Кореи, мягче и дождливее Сеула. Мягкие зимы (5–10 °C), влажное лето, пик осадков — в июльский муссон."},"seasonalVariations":[{"season":"Весна (март–май)","description":"В конце марта — начале апреля вдоль побережья «Блюлайн» цветёт вишня: поездка в капсуле в сезон цветения — лучшая в году. Ясные утренние часы в храме."},{"season":"Лето (июнь–август)","description":"Длинный световой день, и на побережье прохладнее, чем в центре города; июльские муссоны могут сократить время на скайвоке. Часы работы капсулы продлеваются на вечер."},{"season":"Осень (сентябрь–ноябрь)","description":"Самое ясное небо в году — лучшая видимость со стеклянного пола Таритдоль и самые сочные краски со смотровых точек Камчхона."},{"season":"Зима (декабрь–февраль)","description":"Меньше всего людей на каждой остановке; прозрачный свет для фотографий. Капсула отапливается; на террасы храма и в переулки деревень одевайтесь теплее."}]}},{"id":"booking_support","section_html_id":null,"component":"TourBookingSupportSection","props":{"bookingTrustItems":[{"icon":"check-circle","title":"Лицензированный местный оператор","description":"Лицензия на гидов в Пусане","iconBg":"bg-emerald-50/80","iconColor":"text-emerald-600","body":"Лицензированный местный оператор, регулярно проводящий городские туры по Пусану, с сертифицированными англоговорящими гидами, страховкой транспорта и таймингом маршрута, спланированным так, чтобы по возможности избегать самых загруженных часов в храме."},{"icon":"users","title":"Мини-группа","description":"Максимум ≈12 гостей","iconBg":"bg-pink-50/80","iconColor":"text-pink-600","body":"Минивэн для мини-группы (максимум ~12) сохраняет комфорт в узких переулках Камчхона и на 108-ступенчатом пути Ёнгунса — это совсем не то, что автобусные туры на 40 человек."},{"icon":"shield","title":"Вход всюду включён","description":"Основные входные билеты покрыты","iconBg":"bg-sky-50/80","iconColor":"text-sky-600","body":"Все семь основных остановок — с бесплатным входом, поэтому на базовом маршруте в этот день нет скрытых платежей за посещения."}],"bookingSupportSteps":[{"timing":"Сразу","title":"Мгновенное подтверждение","detail":"Подтверждение бронирования с кратким маршрутом","description":"Мгновенное подтверждение бронирования с инструкциями по точке посадки (вокзал Пусана / Сомён / Хэундэ)."},{"timing":"За день до тура","title":"Детали посадки","detail":"Точное место посадки и данные транспорта через WhatsApp","description":"Накануне приходит проверка погоды и заметки по маршруту (совет о поезде «Дануби» для Тхэчжондэ, время приливов у Ёнгунса)."},{"timing":"Утром в день тура","title":"Подтверждение посадки","detail":"Водитель выходит на связь за 10 минут до прибытия","description":"Номер минивэна и контакт гида подтверждаются накануне вечером."},{"timing":"Во время тура","title":"Поддержка в туре","detail":"Прямая связь с операционной службой","description":"Утреннее сообщение подтверждает вашу станцию посадки и ситуацию с трафиком в реальном времени."},{"timing":"В конце дня","title":"Гибкая высадка","detail":"Выберите высадку: Нампхо-дон, вокзал Пусана, Сомён или Хэундэ","description":"Гид рассказывает на месте на каждой остановке — основание Ёнгунса в 1376 году, история 22 наций Мемориального кладбища ООН, происхождение Камчхона как поселения беженцев 1955 года."},{"timing":"После тура","title":"Отзыв и обратная связь","detail":"Отзыв и продолжение общения по желанию","description":"После тура приходит запрос обратной связи; на вопросы о ресторанах Пусана отвечаем в тот же день."}]}},{"id":"faq","section_html_id":"faq","component":"TourFaqSection","props":{"staticQuestions":[{"question":"Включён ли билет на Sky Capsule?","answer":"На ваш выбор при бронировании. Выберите вариант с включённым билетом — и мы заранее резервируем капсулы для вашей группы (цена за капсулу: около ₩30,000 за 2 чел. / ₩39,000 за 3 / ₩44,000 за 4, в одну сторону — вариант с включённым билетом рассчитан из расчёта 2 человека на капсулу). Выберите базовый вариант — и, пока другие едут в капсуле, вы можете пройтись по бесплатной деревянной набережной Green Railway или доехать до Мипхо на микроавтобусе."},{"question":"Нужно ли бронировать Sky Capsule заранее?","answer":"Слоты на закат и на выходные распродаются за 1–2 недели. Если вы выбрали вариант с включённым билетом, мы оформляем резерв для вашей группы сразу после подтверждения бронирования. Купить билет в кассе в тот же день возможно в спокойные будни, но это не гарантировано."},{"question":"Включён ли обед?","answer":"Нет — обед оплачивается отдельно (около ₩10,000–15,000). Гид порекомендует местные варианты у Хэундэ/Мипхо: твэджи-кукпаб (돼지국밥) — фирменный пусанский суп со свининой и рисом, холодную лапшу мильмён или ресторан морепродуктов."},{"question":"Сколько нужно ходить и насколько крутые подъёмы?","answer":"Умеренно-сложно короткими отрезками: 108 ступеней вниз и обратно вверх в Ёнгунса, ровный стеклянный скайвок на Таритдоль, почти ровные участки у станций капсулы, переулки на склоне в Камчхоне и лестницы в Такпатколе — где бесплатный монорельс поднимается за вас. Общая дистанция пешком — около 4–5 км."},{"question":"Подходит ли тур детям и пожилым?","answer":"Да — для большинства активных путешественников. Детям очень нравятся стеклянный пол и капсула, а монорельс в Такпатколе избавляет от самого крутого подъёма. Лестница в Ёнгунса и склоны Камчхона — два самых требовательных участка: проходите их не спеша и при необходимости пропускайте боковые переулки."},{"question":"Чем этот тур отличается от однодневного тура «Главные достопримечательности Пусана»?","answer":"Тот же оператор, другой фокус. «Главные достопримечательности» охватывают классический городской набор (Мемориальное кладбище ООН, рынок Чагальчхи). Этот маршрут в мини-группе делает ставку на побережье и деревни: отдельная остановка на скайвоке Таритдоль, поездка на Sky Capsule с вариантом включённого билета и тихая деревня фресок Такпатколь, мимо которой большие автобусы проезжают."},{"question":"Где посадка и высадка?","answer":"Посадка на трёх центральных станциях — Сомён (08:30), вокзал Пусана (08:50), Хэундэ (09:30). Высадки идут последовательно: Нампхо-дон, вокзал Пусана, Сомён, затем Хэундэ — примерно с 17:50 до 19:00."},{"question":"Что будет, если пойдёт дождь?","answer":"Тур проходит в любую погоду. Капсула и монорельс работают при обычном дожде (останавливаются только при сильном ветре), на скайвоке выдают бахилы, а по переулкам деревень можно гулять с зонтом. При сильной непогоде время на открытых террасах храма может быть сокращено."}]}},{"id":"reviews","section_html_id":"reviews","component":"TourReviewsSection","props":{"guestReviews":[],"reviewsSummary":{"averageRating":0,"totalReviews":0,"ratingDistribution":[{"stars":5,"count":0,"percentage":0},{"stars":4,"count":0,"percentage":0},{"stars":3,"count":0,"percentage":0},{"stars":2,"count":0,"percentage":0},{"stars":1,"count":0,"percentage":0}],"highlights":[]}}},{"id":"sticky_booking","section_html_id":null,"component":"TourStickyBookingBar","props":{"note":"Выберите дату и размер группы, чтобы проверить актуальную доступность и завершить бронирование.","price":{"amountLabel":"59","currency":"USD","per":"person","salePriceUsd":59}}}]}'::jsonb
)
